/* ═══════════════════════════════════════════════════════════════
   NAMAZ DOSTU — HADİS HAVUZU (HADIS_HAVUZU)
   Kaynaklar: Buhârî, Müslim, Tirmizî, Ebû Dâvûd, Nesâî, İbn Mâce,
   Muvatta, Ahmed b. Hanbel, Riyâzü's-Sâlihîn, Hadislerle İslâm (DİB).
   Biçim: { t: Türkçe meal (sadeleştirilmiş), s: kaynak, a: Arapça (opsiyonel) }
   Günün Hadisi ve "1000 Hadis" bölümü bu havuzu mevcut HADITHS ve
   KIRK_HADIS listeleriyle birleştirip (tekrarlar ayıklanarak) kullanır.
   ═══════════════════════════════════════════════════════════════ */
const HADIS_HAVUZU = [
/* ── NİYET, İHLAS, İMAN, TEVHİD ── */
{ a: "الدِّينُ النَّصِيحَةُ", t: "Din nasihattir (samimiyettir). Sahâbîler: Kimin için ey Allah'ın Resûlü? dediler. Allah için, Kitabı için, Resûlü için, Müslümanların yöneticileri ve bütün Müslümanlar için buyurdu.", s: "Müslim, Îmân 95" },
{ t: "İman yetmiş küsur şubedir. En üstünü 'Lâ ilâhe illallah' demek, en alt derecesi yoldan eziyet veren şeyi kaldırmaktır. Hayâ da imandan bir şubedir.", s: "Buhârî, Müslim" },
{ t: "Sizden biriniz kendisi için istediğini kardeşi için de istemedikçe iman etmiş olmaz.", s: "Buhârî, Müslim" },
{ t: "Kalbinde zerre kadar kibir bulunan kimse cennete giremez.", s: "Müslim, Îmân 147" },
{ t: "Allah sizin suretlerinize ve mallarınıza bakmaz; kalplerinize ve amellerinize bakar.", s: "Müslim, Birr 34" },
{ t: "Kim Allah'ın rızasını kazanmak için bir bilgiyi, dünyalık elde etmek amacıyla öğrenirse, kıyamet günü cennetin kokusunu bile alamaz.", s: "Ebû Dâvûd, İlim 12" },
{ t: "Mümin, bir delikten iki defa ısırılmaz.", s: "Buhârî, Müslim" },
{ t: "Sizin en hayırlınız, ahlâkı en güzel olanınızdır.", s: "Buhârî, Müslim" },
{ t: "Güçlü kimse, insanları güreşte yenen değil; öfkelendiğinde kendine hâkim olabilendir.", s: "Buhârî, Müslim" },
{ t: "Mümin, yumuşak huylu, cana yakın ve kolaylık gösteren kimsedir. Cana yakın olmayan ve kendisiyle ünsiyet kurulamayan kimsede hayır yoktur.", s: "Ahmed b. Hanbel, Müsned" },
{ t: "Kim 'Lâ ilâhe illallah' der ve Allah'tan başka tapılanları reddederse, malı ve canı haram (dokunulmaz) olur; hesabı Allah'a aittir.", s: "Müslim, Îmân 37" },
{ t: "İhsan, Allah'ı görüyormuşçasına O'na ibadet etmendir. Sen O'nu görmesen de O seni görüyor.", s: "Buhârî, Müslim" },
{ t: "Şüphesiz Allah, kulunun bir işi yaptığında onu sağlam ve güzel yapmasını sever.", s: "Beyhakî, Şuabü'l-Îmân" },
{ t: "Kim bir iyilik yapmaya niyet eder de yapamazsa, Allah ona bir sevap yazar. Yaparsa on katından yedi yüz katına kadar sevap yazar.", s: "Buhârî, Müslim" },
{ t: "Kim bir kötülük yapmaya niyet eder de vazgeçerse, Allah ona tam bir sevap yazar. Yaparsa yalnız bir günah yazar.", s: "Buhârî, Müslim" },
{ t: "Kalp bir et parçasıdır; o düzelirse bütün beden düzelir, o bozulursa bütün beden bozulur.", s: "Buhârî, Müslim" },
{ t: "Helâl bellidir, haram bellidir. İkisi arasında pek çok insanın bilmediği şüpheli şeyler vardır. Şüphelilerden sakınan dinini ve namusunu korumuş olur.", s: "Buhârî, Müslim" },
{ t: "Allah'ım! Sana teslim oldum, sana inandım, sana güvendim, sana yöneldim.", s: "Buhârî, Müslim" },
{ t: "Kişi dostunun dini üzeredir. Öyleyse her biriniz kiminle dostluk kurduğuna dikkat etsin.", s: "Ebû Dâvûd, Tirmizî" },
{ t: "İmanın tadını; Allah'ı Rab, İslâm'ı din, Muhammed'i peygamber olarak kabul edip razı olan kimse tatmıştır.", s: "Müslim, Îmân 56" },
{ t: "Üç şey kimde bulunursa imanın tadını alır: Allah ve Resûlünü her şeyden çok sevmek, sevdiğini yalnız Allah için sevmek, küfre dönmekten ateşe atılmaktan korkar gibi korkmak.", s: "Buhârî, Müslim" },
{ t: "Kim Allah için sever, Allah için buğzeder, Allah için verir ve Allah için vermezse imanını kemale erdirmiş olur.", s: "Ebû Dâvûd, Sünnet 15" },
{ t: "Sizden hiçbiriniz, ben kendisine anasından, babasından, çocuğundan ve bütün insanlardan daha sevimli olmadıkça iman etmiş olmaz.", s: "Buhârî, Müslim" },
{ t: "Bir kul Allah'a hüsnüzan (güzel zan) beslesin; çünkü Allah 'Ben kulumun beni zannettiği gibiyim' buyurur.", s: "Buhârî, Müslim" },
{ t: "Riyâ (gösteriş), gizli şirktir.", s: "İbn Mâce, Zühd 21" },
{ t: "Sizin için en çok korktuğum şey küçük şirk olan riyâdır.", s: "Ahmed b. Hanbel, Müsned" },
{ t: "Allah'ın kulları üzerindeki hakkı, yalnız O'na ibadet etmeleri ve hiçbir şeyi O'na ortak koşmamalarıdır. Kulların Allah üzerindeki hakkı ise O'na ortak koşmayana azap etmemesidir.", s: "Buhârî, Müslim" },
{ t: "Kim Allah'a hiçbir şeyi ortak koşmadan ölürse cennete girer.", s: "Buhârî, Müslim" },
{ t: "Bütün amellerin en faziletlisi Allah'a ve Resûlüne imandır.", s: "Buhârî, Müslim" },
{ t: "Münafığın alâmeti üçtür: Konuşunca yalan söyler, söz verince sözünde durmaz, kendisine bir şey emanet edilince hıyanet eder.", s: "Buhârî, Müslim" },
{ t: "Dört şey kimde bulunursa tam münafıktır: Emanete hıyanet eder, konuşunca yalan söyler, söz verince sözünde durmaz, tartışınca haddi aşar.", s: "Buhârî, Müslim" },
{ t: "İslâm'ı yaşayan kimseye ne mutlu! Ona yetecek kadar rızık verilmiş ve Allah verdiğine kanaat etmesini nasip etmiştir.", s: "Müslim, Zekât 125" },
{ t: "Allah, dininde derin anlayış (fıkıh) verdiği kimseye hayır dilemiştir.", s: "Buhârî, Müslim" },
{ t: "Şüphesiz Allah, bu dini günahkâr bir kimseyle de destekler.", s: "Buhârî, Müslim" },
{ t: "Kim bir hayra öncülük ederse, onu yapan kadar sevap kazanır.", s: "Müslim, İmâre 133" },
{ t: "Kim hidayete çağırırsa, kendisine uyanların sevabı kadar sevap alır; onların sevabından da hiçbir şey eksilmez.", s: "Müslim, İlim 16" },
{ t: "Kim bir sapıklığa çağırırsa, kendisine uyanların günahı kadar günah yüklenir; onların günahından da bir şey eksilmez.", s: "Müslim, İlim 16" },
{ t: "İman Yemen'lidir, hikmet Yemen'lidir.", s: "Buhârî, Müslim" },
{ t: "Din kolaylıktır. Kim dini zorlaştırırsa din ona galip gelir. Orta yolu tutun, en iyisine yaklaşın, müjdeleyin.", s: "Buhârî, Îmân 29" },
{ t: "Kimin son sözü 'Lâ ilâhe illallah' olursa cennete girer.", s: "Ebû Dâvûd, Cenâiz 20" },
{ t: "İslâm garip başladı, başladığı gibi yine garip olacaktır. Ne mutlu gariplere!", s: "Müslim, Îmân 232" },
{ t: "Allah'a ve ahiret gününe iman eden kimse ya hayır söylesin ya da sussun.", s: "Buhârî, Müslim" },
{ t: "Allah'a ve ahiret gününe iman eden kimse komşusuna ikram etsin.", s: "Buhârî, Müslim" },
{ t: "Allah'a ve ahiret gününe iman eden kimse misafirine ikram etsin.", s: "Buhârî, Müslim" },
{ t: "Kim bir mümini bir sıkıntıdan kurtarırsa, Allah da onu kıyamet günü sıkıntılarından birinden kurtarır.", s: "Müslim, Zikir 38" },
{ t: "Kim bir Müslümanın ayıbını örterse, Allah da dünya ve ahirette onun ayıbını örter.", s: "Müslim, Zikir 38" },
{ t: "Kul, kardeşinin yardımında olduğu sürece Allah da onun yardımındadır.", s: "Müslim, Zikir 38" },
{ t: "Kim ilim tahsil etmek için bir yola girerse, Allah ona cennete giden yolu kolaylaştırır.", s: "Müslim, Zikir 38" },
{ t: "Bir topluluk Allah'ın evlerinden birinde toplanıp Kur'an okur ve aralarında müzakere ederse, üzerlerine huzur iner, rahmet kaplar, melekler kuşatır ve Allah onları katındakilere anar.", s: "Müslim, Zikir 38" },
{ t: "Ameli kendisini geride bırakan kimseyi nesebi (soyu) ileri götürmez.", s: "Müslim, Zikir 38" },
{ t: "Kolaylaştırın, zorlaştırmayın; sükûnet verin, nefret ettirmeyin.", s: "Buhârî, Müslim" },
{ t: "Bir kimse Müslüman olur, İslâm'ı güzelce yaşarsa, Allah onun önceden yaptığı her kötülüğü örter; sonrasında kısas (misliyle karşılık) vardır: iyilik on katından yedi yüz katına kadar, kötülük ise misliyle.", s: "Buhârî, Îmân 31" },
{ t: "Allah katında amellerin en sevimlisi, az da olsa devamlı olanıdır.", s: "Buhârî, Müslim" },
{ t: "Orta yolu tutun, doğruya yakın olun ve bilin ki hiçbiriniz ameli sayesinde kurtulamaz. Allah'ın rahmeti olmadıkça ben de kurtulamam.", s: "Buhârî, Müslim" },
{ t: "Kişi sevdiğiyle beraberdir.", s: "Buhârî, Müslim" },
{ t: "Müminler birbirini sevmede, birbirine merhamet etmede tek bir vücut gibidir; bir organı rahatsız olunca diğer organlar da uykusuzluk ve ateşle ona katılır.", s: "Buhârî, Müslim" },
{ t: "Mümin mümin için, parçaları birbirine kenetlenmiş bir bina gibidir.", s: "Buhârî, Müslim" },
{ t: "Sizden biriniz, yanındaki kardeşi açken tok yatarsa mümin değildir.", s: "Taberânî, el-Mu'cemü'l-Kebîr" },
{ t: "Nerede olursan ol, Allah'tan kork. Kötülüğün ardından bir iyilik yap ki onu silsin. İnsanlara güzel ahlâkla davran.", s: "Tirmizî, Birr 55" },
{ t: "Takvâ işte buradadır (diyerek göğsünü işaret etti).", s: "Müslim, Birr 32" },
{ t: "Sizden biriniz Allah'a kavuşmayı severse Allah da ona kavuşmayı sever.", s: "Buhârî, Müslim" },
{ t: "Dünya müminin zindanı, kâfirin cennetidir.", s: "Müslim, Zühd 1" },
{ t: "Her ümmetin bir fitnesi vardır; ümmetimin fitnesi maldır.", s: "Tirmizî, Zühd 26" },
{ t: "Zenginlik mal çokluğu değildir; asıl zenginlik gönül zenginliğidir.", s: "Buhârî, Müslim" },
{ t: "Mümin kardeşine gülümsemen sadakadır.", s: "Tirmizî, Birr 36" },
{ t: "Her iyilik sadakadır.", s: "Buhârî, Müslim" },
{ t: "Kim güzel bir çığır açarsa, ona hem kendi sevabı hem de onunla amel edenlerin sevabı verilir. Kim kötü bir çığır açarsa, ona kendi günahıyla birlikte onunla amel edenlerin günahı yüklenir.", s: "Müslim, Zekât 69" },
{ t: "Allah bir kula hayır dilerse onu dünyada cezalandırır (günahından temizler).", s: "Tirmizî, Zühd 57" },
{ t: "Mükâfatın büyüklüğü belânın büyüklüğüne göredir. Allah bir topluluğu severse onları imtihan eder; razı olana rıza, kızana gazap vardır.", s: "Tirmizî, Zühd 57" },
{ t: "Müminin durumu hayret vericidir; her işi onun için hayırdır. Bu yalnız mümine hastır: Sevinirse şükreder, hayır olur; başına bir sıkıntı gelirse sabreder, yine hayır olur.", s: "Müslim, Zühd 64" },
{ t: "Ümmetim rahmet olunmuş bir ümmettir.", s: "Ebû Dâvûd, Fiten 7" },
{ t: "Ümmetimin başı mı hayırlıdır sonu mu bilinmez; o yağmur gibidir.", s: "Tirmizî, Edeb 81" },
{ t: "Kim benim sünnetimden yüz çevirirse benden değildir.", s: "Buhârî, Müslim" },
{ t: "Size iki şey bırakıyorum; onlara sımsıkı sarıldığınız sürece asla sapıtmazsınız: Allah'ın Kitabı ve Resûlünün sünneti.", s: "Muvatta, Kader 3" },
{ t: "Benim ve raşid halifelerimin sünnetine sarılın, ona azı dişlerinizle yapışın. Sonradan çıkarılan işlerden sakının; her bid'at sapıklıktır.", s: "Ebû Dâvûd, Tirmizî" },
{ t: "Kim bizim dinimizde olmayan bir şeyi ortaya çıkarırsa o merduttur (kabul edilmez).", s: "Buhârî, Müslim" },
{ t: "Kişinin kendisini ilgilendirmeyen şeyleri bırakması, Müslümanlığının güzelliğindendir.", s: "Tirmizî, Zühd 11" },
{ t: "Bana yakın olan takvâ sahipleridir; kim ve nerede olurlarsa olsunlar.", s: "Ahmed b. Hanbel, Müsned" },
{ t: "Allah'ım, beni hidayete ulaştır ve doğru yolda sabit kıl.", s: "Müslim, Zikir 78" },
{ t: "Rabbim! Bana bağışla, bana merhamet et, beni doğru yola ilet, bana afiyet ve rızık ver.", s: "Müslim, Zikir 35" },
{ t: "Kim şüpheli şeylerden sakınırsa dinini ve ırzını korumuş olur; kim şüpheli şeylere düşerse harama düşer.", s: "Buhârî, Müslim" },
{ t: "Sana şüphe vereni bırak, şüphe vermeyene bak.", s: "Tirmizî, Nesâî" },
{ t: "İyilik, gönlünün huzur bulduğu şeydir. Günah ise içini tırmalayan ve insanların bilmesini istemediğin şeydir.", s: "Müslim, Birr 14" },
{ t: "Fetva verenler sana fetva verse de sen kalbine danış.", s: "Ahmed b. Hanbel, Dârimî" },
{ t: "Seni şüpheye düşüren şeyi bırak, düşürmeyeni al. Doğruluk kalbin huzurudur, yalan ise şüphedir.", s: "Tirmizî, Kıyâme 60" },
{ t: "Sizden biriniz din kardeşini seviyorsa ona sevdiğini söylesin.", s: "Ebû Dâvûd, Tirmizî" },
{ t: "Allah katında en sevimli isimler Abdullah ve Abdurrahman'dır.", s: "Müslim, Âdâb 2" },
{ t: "Kıyamet günü Allah'a en yakın olanınız, ahlâkça en güzel olanınızdır.", s: "Tirmizî, Birr 71" },
{ t: "Mümin kardeşinin ihtiyacını gideren kimsenin ihtiyacını Allah giderir.", s: "Buhârî, Müslim" },
{ t: "Sizden önceki ümmetlerin hastalığı size de bulaştı: haset ve kin. Kin tıraş edicidir; saçı değil, dini tıraş eder.", s: "Tirmizî, Sıfatü'l-Kıyâme 56" },
{ t: "Sizin ahirette en yüksek dereceye erecek olanlarınız, insanları en çok sevip onlara en güler yüzlü davrananlarınızdır.", s: "Ahmed b. Hanbel, Müsned" },
{ t: "Allah, insanlara merhamet etmeyen kimseye merhamet etmez.", s: "Buhârî, Müslim" },
{ t: "Merhamet edenlere Rahmân merhamet eder. Yeryüzündekilere merhamet edin ki göktekiler de size merhamet etsin.", s: "Ebû Dâvûd, Tirmizî" },
{ t: "Sizden biriniz kardeşinin başına gelen bir sıkıntıya sevinmesin; Allah ona afiyet verir de kendisini imtihan eder.", s: "Tirmizî, Sıfatü'l-Kıyâme 54" },
{ t: "İnsanlara merhamet etmeyen kimseye Allah merhamet etmez.", s: "Buhârî, Müslim" },
{ t: "Mümin insanlarla kaynaşan, kendisiyle kaynaşılan kimsedir.", s: "Ahmed b. Hanbel, Müsned" },
{ t: "İmanı en üstün olanınız, ahlâkı en güzel olanınızdır.", s: "Ebû Dâvûd, Sünnet 15" },
{ t: "Hiçbir baba çocuğuna güzel terbiyeden daha kıymetli bir bağış yapmamıştır.", s: "Tirmizî, Birr 33" },
{ t: "Kim Allah'ın kendisine verdiğine razı olursa insanların en zengini olur.", s: "Tirmizî, Zühd 35" },
{ t: "Allah bir kulu severse Cebrail'e 'Ben falanı seviyorum, sen de sev' der. Cebrail de onu sever ve gök ehline seslenir; sonra yeryüzünde ona kabul (sevgi) konulur.", s: "Buhârî, Müslim" },
{ t: "Allah bir kula hayır dilerse ölümünden önce onu amel işlemeye muvaffak kılar.", s: "Tirmizî, Kader 8" },
{ t: "Kim, günahı için Allah'tan af dilerse, Allah onu bağışlar.", s: "Buhârî, Müslim" },
{ t: "Sizin en hayırlınız, kendisinden hayır umulan ve şerrinden emin olunan kimsedir.", s: "Tirmizî, Fiten 76" },
{ t: "Allah bir kavme azap edeceği zaman içlerindeki iyilerle de azap eder; sonra amellerine göre diriltilirler.", s: "Buhârî, Müslim" },
{ t: "İyilik yapmaya devam edin; Allah size merhamet etsin.", s: "Beyhakî" },
{ t: "İnsanların en hayırlısı, insanlara en faydalı olanıdır.", s: "Taberânî, el-Mu'cemü'l-Evsat" },
{ t: "Allah'ın en sevdiği amel, bir Müslümanı sevindirmen, üzüntüsünü gidermen, borcunu ödemen ya da açlığını gidermendir.", s: "Taberânî, el-Mu'cemü'l-Kebîr" },
{ t: "İyiliğin her türlüsü sadakadır; kardeşini güler yüzle karşılaman da sadakadır.", s: "Tirmizî, Birr 45" },
{ t: "Zerre kadar iyilik ve zerre kadar kötülük karşılıksız kalmaz.", s: "Buhârî, Müslim" },
{ t: "Din, iyi muamele (güzel ahlâk)tır.", s: "Riyâzü's-Sâlihîn" },
{ t: "Mümin dostluğunu saklamaz; dost edinilen ve dost olunan kimsedir.", s: "Ahmed b. Hanbel, Müsned" },
{ t: "Allah'a en sevimli olanınız, ahlâkı en güzel olanınızdır: Alçak gönüllü, cana yakın ve yumuşak huylu olanlar.", s: "Taberânî" },

/* ── NAMAZ, ABDEST, TEMİZLİK, CAMİ, EZAN ── */
{ a: "الصَّلَاةُ عِمَادُ الدِّينِ", t: "Namaz dinin direğidir.", s: "Beyhakî, Şuabü'l-Îmân" },
{ t: "Kulun kıyamet günü ilk hesaba çekileceği şey namazıdır. Namazı düzgün olursa kurtulur ve kazanır; bozuk olursa perişan olur ve hüsrana uğrar.", s: "Tirmizî, Salât 188" },
{ t: "Bizimle onlar (kâfirler) arasındaki ahit namazdır; kim namazı terk ederse küfre düşer.", s: "Tirmizî, Nesâî, İbn Mâce" },
{ t: "Beş vakit namaz, iki cuma ve iki Ramazan, aralarında büyük günahlardan sakınıldığı takdirde günahlara kefarettir.", s: "Müslim, Tahâret 16" },
{ t: "Birinizin kapısının önünden akan bir nehir olsa ve günde beş defa yıkansa, kirinden bir şey kalır mı? İşte beş vakit namaz da böyledir; Allah onunla günahları siler.", s: "Buhârî, Müslim" },
{ t: "Namaz nurdur, sadaka burhandır, sabır ışıktır, Kur'an ya lehinde ya aleyhinde delildir.", s: "Müslim, Tahâret 1" },
{ t: "Temizlik imanın yarısıdır.", s: "Müslim, Tahâret 1" },
{ t: "Abdesti güzelce alan Müslümanın günahları, tırnak altlarına varıncaya kadar dökülür.", s: "Müslim, Tahâret 33" },
{ t: "Kim güzelce abdest alır, sonra namaza gitmek için evinden çıkarsa, attığı her adım için bir derecesi yükselir ve bir günahı silinir.", s: "Buhârî, Müslim" },
{ t: "Sizden biriniz namazda olduğu sürece, namazı beklediği sürece namazdadır ve melekler onun için dua eder.", s: "Buhârî, Müslim" },
{ t: "Cemaatle kılınan namaz, tek başına kılınan namazdan yirmi yedi derece daha üstündür.", s: "Buhârî, Müslim" },
{ t: "İnsanlar ezan okumanın ve ilk safta bulunmanın faziletini bilselerdi, kura çekmekten başka yol bulamazlardı.", s: "Buhârî, Müslim" },
{ t: "Kim kırk gün ilk tekbire yetişerek cemaatle namaz kılarsa, ona iki berat yazılır: Cehennemden ve nifaktan berat.", s: "Tirmizî, Salât 64" },
{ t: "Sabah ve yatsı namazlarını cemaatle kılanın sevabını münafıklar bilselerdi, emekleyerek de olsa gelirlerdi.", s: "Buhârî, Müslim" },
{ t: "Kim yatsı namazını cemaatle kılarsa gecenin yarısını, sabahı da cemaatle kılarsa bütün geceyi namazla geçirmiş gibi olur.", s: "Müslim, Mesâcid 260" },
{ t: "Sabah namazını kılan kimse Allah'ın himayesindedir.", s: "Müslim, Mesâcid 261" },
{ t: "Namazların en ağırı münafıklara sabah ve yatsıdır.", s: "Buhârî, Müslim" },
{ t: "İkindi namazını terk eden kimsenin ameli boşa gitmiş gibidir.", s: "Buhârî, Mevâkît 15" },
{ t: "Kim güneş doğmadan önceki (sabah) ve batmadan önceki (ikindi) namazı kılarsa cehenneme girmez.", s: "Müslim, Mesâcid 213" },
{ t: "Ezanı işittiğinizde müezzinin söylediğini siz de söyleyin; sonra bana salât edin; sonra benim için vesileyi isteyin.", s: "Müslim, Salât 11" },
{ t: "Ezan ile kamet arasında yapılan dua reddedilmez.", s: "Ebû Dâvûd, Tirmizî" },
{ t: "Gecenin son üçte birinde Rabbimiz dünya semasına iner ve 'Bana dua eden yok mu, kabul edeyim; benden isteyen yok mu, vereyim; benden af dileyen yok mu, bağışlayayım' buyurur.", s: "Buhârî, Müslim" },
{ t: "Farz namazlardan sonra en faziletli namaz gece namazıdır.", s: "Müslim, Sıyâm 202" },
{ t: "Gece namazına devam edin; o sizden önceki salihlerin âdetidir, Rabbinize yakınlıktır, günahlara kefarettir.", s: "Tirmizî, Deavât 101" },
{ t: "Namazda kulun Rabbine en yakın olduğu an secde hâlidir; orada duayı çok yapın.", s: "Müslim, Salât 215" },
{ t: "Kul secde ettiğinde şeytan ağlayarak bir kenara çekilir ve 'Âdemoğlu secdeyle emrolundu, secde etti, cennet onun; ben emrolundum, karşı geldim, ateş benim' der.", s: "Müslim, Îmân 133" },
{ t: "Namazda huşû ile durun; çünkü namaz, göz aydınlığımdır.", s: "Nesâî, İşretü'n-Nisâ 1" },
{ t: "Bana dünyanızdan üç şey sevdirildi: Güzel koku, kadınlar; namaz ise gözümün nuru kılındı.", s: "Nesâî, Ahmed b. Hanbel" },
{ t: "Ey Bilal, kalk namaza; bizi onunla rahatlat.", s: "Ebû Dâvûd, Edeb 78" },
{ t: "Kim sabah namazını cemaatle kılıp güneş doğuncaya kadar oturup Allah'ı zikreder, sonra iki rekât namaz kılarsa, tam bir hac ve umre sevabı alır.", s: "Tirmizî, Cum'a 59" },
{ t: "Her gün farzların dışında on iki rekât namaz kılana Allah cennette bir köşk yapar.", s: "Müslim, Müsâfirîn 103" },
{ t: "Kim öğleden önce dört, sonra dört rekât kılmaya devam ederse Allah onu cehenneme haram kılar.", s: "Tirmizî, Ebû Dâvûd" },
{ t: "Sabah namazının iki rekât sünneti, dünya ve içindekilerden daha hayırlıdır.", s: "Müslim, Müsâfirîn 96" },
{ t: "Vitir namazını kılın; Allah tektir, teki sever.", s: "Ebû Dâvûd, Vitr 1" },
{ t: "Duha (kuşluk) namazına devam edenin günahları deniz köpüğü kadar da olsa bağışlanır.", s: "Tirmizî, Vitr 15" },
{ t: "Her sabah sizin her eklem için bir sadaka vermeniz gerekir; kuşluk vakti kılınan iki rekât bunların hepsine yeter.", s: "Müslim, Müsâfirîn 84" },
{ t: "Evlerinizi kabirlere çevirmeyin; namazınızın bir kısmını evlerinizde kılın.", s: "Buhârî, Müslim" },
{ t: "Kişinin en faziletli namazı, farzlar hariç evinde kıldığıdır.", s: "Buhârî, Müslim" },
{ t: "Namazı, dünyaya veda eden kimsenin namazı gibi kıl.", s: "İbn Mâce, Zühd 15" },
{ t: "Namaz kılarken sağa sola bakmak, şeytanın kulun namazından kaptığı bir şeydir.", s: "Buhârî, Ezân 93" },
{ t: "Hırsızlığın en kötüsü, namazından çalanınkidir. Rükûunu ve secdesini tam yapmayandır.", s: "Ahmed b. Hanbel, Müsned" },
{ t: "Saflarınızı düzeltin; safları düzeltmek namazın tamamındandır.", s: "Buhârî, Müslim" },
{ t: "Saflarınızı düz tutun, yoksa Allah aranızı (kalplerinizi) ayırır.", s: "Buhârî, Müslim" },
{ t: "Erkeklerin en hayırlı safı ilk saf, en kötüsü son saftır. Kadınların en hayırlı safı son saf, en kötüsü ilk saftır.", s: "Müslim, Salât 132" },
{ t: "İmam, kendisine uyulmak için öne geçirilmiştir; o tekbir alınca siz de alın, rükû edince rükû edin.", s: "Buhârî, Müslim" },
{ t: "İmamdan önce başını kaldıran kimse, Allah'ın onun başını eşek başına çevirmesinden korkmaz mı?", s: "Buhârî, Müslim" },
{ t: "Kim bir camiyi Allah rızası için yaparsa, Allah da ona cennette bir ev yapar.", s: "Buhârî, Müslim" },
{ t: "Camiye devam eden kimseyi gördüğünüzde onun imanına şahitlik edin.", s: "Tirmizî, Îmân 8" },
{ t: "Karanlıkta mescitlere yürüyenleri kıyamet günü tam bir nur ile müjdele.", s: "Ebû Dâvûd, Tirmizî" },
{ t: "Kişinin evinden ve pazardan uzaklığı arttıkça namaz için attığı adımların sevabı da artar.", s: "Müslim, Mesâcid 277" },
{ t: "Kamet getirildiğinde koşarak değil, sükûnetle ve vakarla yürüyün; yetiştiğinizi kılın, kaçırdığınızı tamamlayın.", s: "Buhârî, Müslim" },
{ t: "Namaza sükûnetle gelin; ne yetişirseniz kılın, kaçırdığınızı tamamlayın.", s: "Buhârî, Müslim" },
{ t: "Cuma günü gusledip mescide erkenden gidenin sevabı, deve kurban etmiş gibidir.", s: "Buhârî, Müslim" },
{ t: "Cuma günü güneşin doğduğu en hayırlı gündür: Âdem o gün yaratıldı, o gün cennete konuldu, o gün cennetten çıkarıldı; kıyamet de cuma günü kopacaktır.", s: "Müslim, Cum'a 18" },
{ t: "Cuma gününde öyle bir saat vardır ki, Müslüman bir kul o saatte namaz kılıp Allah'tan bir şey isterse Allah ona mutlaka verir.", s: "Buhârî, Müslim" },
{ t: "Kim üç cumayı umursamadan terk ederse, Allah onun kalbini mühürler.", s: "Ebû Dâvûd, Tirmizî" },
{ t: "Cuma günü imam hutbe okurken arkadaşına 'sus' desen bile boş söz etmiş olursun.", s: "Buhârî, Müslim" },
{ t: "Cuma namazı, ergenlik çağına gelen her Müslüman erkeğe farzdır.", s: "Nesâî, Cum'a 2" },
{ t: "Bir kimse Cuma günü Kehf sûresini okursa, iki cuma arası nur ile aydınlanır.", s: "Hâkim, el-Müstedrek" },
{ t: "Bana cuma günü ve gecesi çok salavat getirin; salavatınız bana ulaştırılır.", s: "Beyhakî, Sünen" },
{ t: "Kim güzelce abdest alıp cumaya gider, sessizce hutbeyi dinlerse, iki cuma arası ve üç gün fazlası bağışlanır.", s: "Müslim, Cum'a 27" },
{ t: "Namaza durduğunda tekbir al, sonra Kur'an'dan kolayına geleni oku; sonra rükûya var, tam bir sükûnetle dur; sonra kalk, tam doğrul; sonra secdeye var, sükûnetle dur; sonra otur, sükûnetle dur.", s: "Buhârî, Müslim" },
{ t: "Fatiha'sız namaz olmaz.", s: "Buhârî, Müslim" },
{ t: "Bir kimsenin namazı, rükû ve secdede belini tam doğrultmadıkça kâmil olmaz.", s: "Ebû Dâvûd, Tirmizî" },
{ t: "Namazda esnemek şeytandandır; biriniz esneyeceği zaman gücü yettiğince tutsun.", s: "Tirmizî, Salât 156" },
{ t: "Öğle sıcağını serinliğe bırakın (öğleyi biraz geciktirin); sıcağın şiddeti cehennemin kaynamasındandır.", s: "Buhârî, Müslim" },
{ t: "Kim sabah namazını kılarsa akşama kadar Allah'ın zimmetindedir.", s: "Müslim, Mesâcid 262" },
{ t: "Kim güneş doğmadan önce ve batmadan önce namazı kılarsa ateşe girmez.", s: "Müslim, Mesâcid 213" },
{ t: "Sizden biri uyuyup namazı kaçırırsa ya da unutursa, hatırladığında kılsın; bunun başka kefareti yoktur.", s: "Buhârî, Müslim" },
{ t: "Namaz vakti girince sizden biri ezan okusun, en büyüğünüz (yaşça) imam olsun.", s: "Buhârî, Müslim" },
{ t: "Bir kavme Allah'ın Kitabı'nı en iyi okuyan imam olsun.", s: "Müslim, Mesâcid 290" },
{ t: "Namaz kılarken önüne sütre koy; şeytanın namazını kesmesine izin verme.", s: "Ebû Dâvûd, Salât 107" },
{ t: "Her kim güzel abdest alır ve iki rekât namaz kılıp kalbi ve yüzüyle o namaza yönelirse, ona cennet vacip olur.", s: "Ebû Dâvûd, Nesâî" },
{ t: "Abdest üzerine abdest, nur üzerine nurdur.", s: "Riyâzü's-Sâlihîn" },
{ t: "Misvak ağzı temizler, Rabbi razı eder.", s: "Nesâî, Tahâret 5" },
{ t: "Ümmetime zor gelmeseydi her namazda misvak kullanmalarını emrederdim.", s: "Buhârî, Müslim" },
{ t: "Fıtrattan olan on şey: Bıyığı kısaltmak, sakalı bırakmak, misvak kullanmak, burna su vermek, tırnak kesmek, parmak boğumlarını yıkamak, koltuk altı ve etek tıraşı, istinca.", s: "Müslim, Tahâret 56" },
{ t: "Sizden biriniz uykudan uyandığında elini yıkamadan kaba daldırmasın; elinin nerede gecelediğini bilmez.", s: "Buhârî, Müslim" },
{ t: "Kim abdest alıp 'Eşhedü en lâ ilâhe illallah ve eşhedü enne Muhammeden abduhû ve resûlüh' derse, cennetin sekiz kapısı ona açılır, dilediğinden girer.", s: "Müslim, Tahâret 17" },
{ t: "Kıyamet günü ümmetim, abdest izlerinden dolayı yüzleri ve elleri parlak olarak çağrılır.", s: "Buhârî, Müslim" },
{ t: "Ümmetimden, abdest izleriyle yüzleri, elleri ve ayakları parlayanları havuzumun başında tanırım.", s: "Buhârî, Müslim" },
{ t: "Allah, temizlik olmadan namazı ve hıyanetle elde edilen maldan sadakayı kabul etmez.", s: "Müslim, Tahâret 2" },
{ t: "Cünüplükten, cuma günü, kan aldırdıktan ve ölü yıkadıktan sonra gusletmek sünnettir.", s: "Ebû Dâvûd, Tahâret 127" },
{ t: "Sizden biriniz namazda şüpheye düşerse şüpheyi atsın, kesin bildiğine göre hareket etsin.", s: "Müslim, Mesâcid 88" },
{ t: "Namazda yanılan kimse iki secde yapsın (sehiv secdesi).", s: "Buhârî, Müslim" },
{ t: "Kim namazı ihmal ederse Allah'ın onu ihmal etmesinden korksun.", s: "Riyâzü's-Sâlihîn" },
{ t: "Namazı vaktinde kılmak Allah'ın en sevdiği ameldir; sonra anne babaya iyilik, sonra Allah yolunda cihattır.", s: "Buhârî, Müslim" },
{ t: "Kim kasten namazı terk ederse Allah'ın zimmeti ondan kalkar.", s: "Ahmed b. Hanbel, Müsned" },
{ t: "Namaz kılmak isteyenin, önüne sütre koyması ve kimsenin önünden geçmesine izin vermemesi gerekir.", s: "Müslim, Salât 258" },
{ t: "Namaz kılanın önünden geçenin ne kadar günah kazandığını bilseydi, kırk yıl beklemeyi tercih ederdi.", s: "Buhârî, Müslim" },
{ t: "Ezanı işittiğinde müezzine icabet et; ezan okunurken konuşma.", s: "Riyâzü's-Sâlihîn" },
{ t: "Müezzinler kıyamet günü insanların en uzun boyunluları olacaktır.", s: "Müslim, Salât 14" },
{ t: "Kimin evinde iki rekât namaz kılınır ve Kur'an okunursa, o ev genişler ve nurlanır.", s: "Riyâzü's-Sâlihîn" },
{ t: "Ey insanlar! Selâmı yayın, yemek yedirin, insanlar uyurken geceleyin namaz kılın; selâmetle cennete girersiniz.", s: "Tirmizî, İbn Mâce" },
{ t: "Allah'ım! Bizi namazı dosdoğru kılanlardan eyle.", s: "Riyâzü's-Sâlihîn" },
{ t: "Kalk ve namaz kıl; çünkü namaz şifadır.", s: "İbn Mâce, Tıb 10" },
{ t: "Sabah namazından sonra 'Allah'ım, bana faydalı ilim, hoş rızık ve makbul amel ver' diye dua edin.", s: "İbn Mâce, İkâme 32" },
{ t: "Namazı bitirdiğinde otuz üç kez sübhânallah, otuz üç kez elhamdülillah, otuz üç kez Allahu ekber de; sonra 'Lâ ilâhe illallahu vahdehû lâ şerîke leh…' de; günahların deniz köpüğü kadar da olsa bağışlanır.", s: "Müslim, Mesâcid 146" },
{ t: "Kim her farz namazın ardından Âyetü'l-Kürsî'yi okursa, cennete girmesine ölümden başka engel kalmaz.", s: "Nesâî, Taberânî" },
{ t: "Ey Muaz! Seni seviyorum; her namazın ardından 'Allah'ım, seni zikretmek, sana şükretmek ve sana güzelce ibadet etmek için bana yardım et' demeyi bırakma.", s: "Ebû Dâvûd, Nesâî" },
{ t: "Kim bir farz namazını kılar, sonra oturup Allah'ı zikrederse melekler ona dua eder.", s: "Buhârî, Müslim" },
{ t: "Rükûda Rabbi tazim edin; secdede duayı çok yapın, kabule en yakın olan budur.", s: "Müslim, Salât 207" },

/* ── ORUÇ, RAMAZAN, ZEKÂT, SADAKA, HAC, KURBAN ── */
{ t: "Kim inanarak ve sevabını Allah'tan bekleyerek Ramazan orucunu tutarsa, geçmiş günahları bağışlanır.", s: "Buhârî, Müslim" },
{ t: "Kim inanarak ve sevabını Allah'tan umarak Kadir gecesini ihya ederse, geçmiş günahları bağışlanır.", s: "Buhârî, Müslim" },
{ t: "Ramazan girince cennet kapıları açılır, cehennem kapıları kapanır ve şeytanlar zincire vurulur.", s: "Buhârî, Müslim" },
{ t: "Oruç kalkandır. Oruçlu kötü söz söylemesin, bağırıp çağırmasın; biri ona sataşırsa 'Ben oruçluyum' desin.", s: "Buhârî, Müslim" },
{ t: "Allah buyurur: Oruç benim içindir, mükâfatını ben veririm. Kulum yemesini, içmesini ve şehvetini benim için bırakır.", s: "Buhârî, Müslim" },
{ t: "Oruçlunun iki sevinci vardır: Biri iftar ettiğinde, diğeri Rabbine kavuştuğunda.", s: "Buhârî, Müslim" },
{ t: "Oruçlunun ağız kokusu Allah katında misk kokusundan daha güzeldir.", s: "Buhârî, Müslim" },
{ t: "Kim yalan sözü ve onunla amel etmeyi bırakmazsa, Allah'ın onun yemesini içmesini bırakmasına ihtiyacı yoktur.", s: "Buhârî, Savm 8" },
{ t: "Sahur yapın; sahurda bereket vardır.", s: "Buhârî, Müslim" },
{ t: "İnsanlar iftarı acele ettikleri (vakti girince hemen açtıkları) sürece hayır üzere olurlar.", s: "Buhârî, Müslim" },
{ t: "Sizden biriniz iftar edeceği zaman hurma ile açsın; bulamazsa su ile açsın, çünkü su temizleyicidir.", s: "Ebû Dâvûd, Tirmizî" },
{ t: "Oruçlu kimse, iftar anında reddedilmeyen bir duaya sahiptir.", s: "İbn Mâce, Sıyâm 48" },
{ t: "Üç kişinin duası reddedilmez: İftar edinceye kadar oruçlunun, adil yöneticinin ve mazlumun duası.", s: "Tirmizî, Deavât 129" },
{ t: "Kim bir oruçluya iftar ettirirse, oruçlunun sevabından hiçbir şey eksilmeksizin onun sevabı kadar sevap kazanır.", s: "Tirmizî, Savm 82" },
{ t: "Bizim orucumuzla Ehl-i Kitab'ın orucu arasındaki fark, sahur yemeğidir.", s: "Müslim, Sıyâm 46" },
{ t: "Cennette Reyyân denilen bir kapı vardır; kıyamet günü oradan yalnız oruçlular girer.", s: "Buhârî, Müslim" },
{ t: "Kim Ramazan'ı tutar, ardından Şevval'den altı gün eklerse, bütün yıl oruç tutmuş gibi olur.", s: "Müslim, Sıyâm 204" },
{ t: "Arefe günü tutulan oruç, geçmiş ve gelecek bir yılın günahlarına kefarettir.", s: "Müslim, Sıyâm 196" },
{ t: "Âşûrâ günü orucu, geçmiş bir yılın günahlarına kefarettir.", s: "Müslim, Sıyâm 197" },
{ t: "Ameller pazartesi ve perşembe günleri arz olunur; ben amelimin oruçluyken arz edilmesini severim.", s: "Tirmizî, Savm 44" },
{ t: "Her aydan üç gün oruç tutmak, bütün yıl oruç tutmak gibidir.", s: "Buhârî, Müslim" },
{ t: "En faziletli oruç, Dâvûd'un orucudur: Bir gün tutar, bir gün tutmazdı.", s: "Buhârî, Müslim" },
{ t: "Ramazan'ın son on gününde geceleri ihya edin, ailenizi uyandırın, ibadet için hazırlanın.", s: "Buhârî, Müslim" },
{ t: "Kadir gecesini Ramazan'ın son on gününün tek gecelerinde arayın.", s: "Buhârî, Müslim" },
{ t: "Kadir gecesi bin aydan hayırlıdır. Kim ondan mahrum kalırsa bütün hayırdan mahrum kalmış olur.", s: "Nesâî, İbn Mâce" },
{ t: "Âişe: 'Kadir gecesine denk gelirsem ne diyeyim?' diye sordu. 'Allahümme inneke afüvvün tühibbü'l-afve fa'fü annî' de buyurdu.", s: "Tirmizî, Deavât 84" },
{ t: "Kim özürsüz olarak Ramazan'dan bir gün oruç tutmazsa, bütün ömrü tutsa onun yerini dolduramaz.", s: "Ebû Dâvûd, Tirmizî" },
{ t: "Oruçlu unutarak yer içerse orucunu tamamlasın; onu Allah yedirmiş ve içirmiştir.", s: "Buhârî, Müslim" },
{ t: "Fıtır sadakası, oruçluyu boş ve kötü sözlerden temizlemek ve yoksullara yiyecek olması için farz kılındı.", s: "Ebû Dâvûd, İbn Mâce" },
{ t: "Sadaka malı eksiltmez. Allah affeden kulunun izzetini artırır. Kim Allah için tevazu gösterirse Allah onu yüceltir.", s: "Müslim, Birr 69" },
{ t: "Sadaka Rabbin gazabını söndürür ve kötü ölümü önler.", s: "Tirmizî, Zekât 28" },
{ t: "Suyun ateşi söndürdüğü gibi sadaka da günahı söndürür.", s: "Tirmizî, Îmân 8" },
{ t: "Her gün iki melek iner; biri 'Allah'ım, verene karşılığını ver', diğeri 'Allah'ım, cimriye telef ver' der.", s: "Buhârî, Müslim" },
{ t: "Bir hurmanın yarısıyla da olsa ateşten korunun; bulamazsanız güzel bir sözle.", s: "Buhârî, Müslim" },
{ t: "Veren el, alan elden üstündür.", s: "Buhârî, Müslim" },
{ t: "Sağ elin verdiğini sol el bilmeyecek şekilde gizlice sadaka veren kimse, Allah'ın gölgesinden başka gölge olmayan günde O'nun gölgesindedir.", s: "Buhârî, Müslim" },
{ t: "Kim helâl kazancından bir hurma kadar sadaka verirse, Allah onu sağ eliyle kabul eder ve dağ gibi oluncaya kadar büyütür.", s: "Buhârî, Müslim" },
{ t: "Sadakanın en faziletlisi, zenginken sağlıklıyken, yaşamayı umup fakirlikten korkarken verilendir.", s: "Buhârî, Müslim" },
{ t: "Sadakanın en hayırlısı, geride zenginlik bırakandır (aileyi muhtaç etmeyendir). Önce geçimini üstlendiklerinden başla.", s: "Buhârî, Müslim" },
{ t: "Bir dinar Allah yolunda, bir dinar köle azadında, bir dinar yoksula, bir dinar ailene harcadın; en büyük sevabı ailene harcadığındır.", s: "Müslim, Zekât 39" },
{ t: "Akrabaya verilen sadaka iki sadakadır: Hem sadaka hem sıla-i rahim.", s: "Tirmizî, Nesâî" },
{ t: "Kimin malında zekât olur da onu ödemezse, kıyamet günü o mal kel bir yılan olup boynuna dolanır.", s: "Buhârî, Zekât 3" },
{ t: "Zekâtı ödenen mal, kenz (biriktirilen ve azap sebebi olan hazine) değildir.", s: "Ebû Dâvûd, Zekât 32" },
{ t: "Malınızı zekâtla koruyun, hastalarınızı sadakayla tedavi edin, belâlara dua ile karşı koyun.", s: "Taberânî" },
{ t: "İnsanın kendi elinin emeğinden daha hayırlı bir yiyeceği yoktur; Dâvûd da elinin emeğinden yerdi.", s: "Buhârî, Büyû' 15" },
{ t: "Kişinin yaptığı en hayırlı harcama, ailesi için yaptığıdır.", s: "Müslim, Zekât 38" },
{ t: "Kim Allah rızası için bir sadaka verirse, o sadaka kıyamet günü ona gölge olur.", s: "Ahmed b. Hanbel, Müsned" },
{ t: "Sizden biriniz komşusuna ikram ettiği, kardeşine yardım ettiği sürece, sadaka veriyor demektir.", s: "Riyâzü's-Sâlihîn" },
{ t: "Bir kişi yol üzerindeki bir dalı kaldırdı da Allah ona teşekkür edip bağışladı.", s: "Buhârî, Müslim" },
{ t: "Bir adam susuz köpeğe kuyudan ayakkabısıyla su çıkarıp içirdi de Allah ona teşekkür edip cennete koydu.", s: "Buhârî, Müslim" },
{ t: "Bir kadın, kediyi hapsedip yiyecek vermediği ve ölüme terk ettiği için cehenneme girdi.", s: "Buhârî, Müslim" },
{ t: "Yoksulu doyurmak, hastayı ziyaret etmek, esiri kurtarmak; bunlar sizin üzerinize haktır.", s: "Buhârî, Nikâh 71" },
{ t: "Yetimi himaye eden kimse ile ben cennette şu ikisi gibi yan yana olacağız (işaret ve orta parmağını gösterdi).", s: "Buhârî, Talâk 25" },
{ t: "Dul ve yoksullara koşan kimse, Allah yolunda cihat eden gibidir; gece namaz kılan, gündüz oruç tutan gibidir.", s: "Buhârî, Müslim" },
{ t: "Dilenmek, yüzü tırmalayan bir yaradır; ancak sultan veya zaruret için istenmesi hariç.", s: "Ebû Dâvûd, Tirmizî" },
{ t: "İnsanlardan bir şey istemeyen, Allah'ın kendisini muhtaç etmemesine kavuşur.", s: "Buhârî, Müslim" },
{ t: "Kim iffetli olmak isterse Allah onu iffetli kılar; kim müstağni olmak isterse Allah onu zengin kılar; kim sabretmeye çalışırsa Allah ona sabır verir.", s: "Buhârî, Müslim" },
{ t: "Zengine sadaka helâl değildir; ancak beş kişiye: Allah yolunda gazi, zekât memuru, borçlu, malıyla satın alan ve yoksul komşusundan hediye alan.", s: "Ebû Dâvûd, Zekât 24" },
{ t: "Hac, kendinden önceki günahları siler.", s: "Müslim, Îmân 192" },
{ t: "Makbul haccın karşılığı cennetten başkası değildir.", s: "Buhârî, Müslim" },
{ t: "Kim hac eder de kötü söz söylemez ve günah işlemezse, annesinden doğduğu gün gibi günahlarından arınmış döner.", s: "Buhârî, Müslim" },
{ t: "Umre, umreye kadar aralarındaki günahlara kefarettir; makbul haccın karşılığı ise cennettir.", s: "Buhârî, Müslim" },
{ t: "Ramazan'da yapılan umre, hac sevabı kazandırır.", s: "Buhârî, Müslim" },
{ t: "Hacca ve umreye devam edin; onlar, körüğün demiri temizlediği gibi fakirliği ve günahları giderir.", s: "Tirmizî, Nesâî" },
{ t: "Kim hac etmek isterse acele etsin.", s: "Ebû Dâvûd, Menâsik 5" },
{ t: "Arefe gününde Allah'ın cehennemden azat ettiği kul sayısı, başka hiçbir günde olduğu kadar değildir.", s: "Müslim, Hac 436" },
{ t: "Hac Arafat'tır.", s: "Tirmizî, Nesâî" },
{ t: "En hayırlı dua Arefe günü yapılan duadır. Benim ve önceki peygamberlerin söylediği en hayırlı söz: Lâ ilâhe illallahu vahdehû lâ şerîke leh…", s: "Tirmizî, Deavât 122" },
{ t: "Hacca gidenler ve umre yapanlar Allah'ın misafirleridir; dua ederlerse kabul eder, bağışlanma dilerlerse bağışlar.", s: "İbn Mâce, Menâsik 5" },
{ t: "Hacer-i Esved cennettendir; sütten daha beyazdı, insanların günahları onu kararttı.", s: "Tirmizî, Hac 49" },
{ t: "Zemzem, ne için içilirse onun içindir.", s: "İbn Mâce, Menâsik 78" },
{ t: "Zemzem suyu bereketlidir; o bir yemek gibi doyurur.", s: "Müslim, Fedâilü's-Sahâbe 132" },
{ t: "Mescid-i Haram'da kılınan namaz başka yerde kılınan yüz bin namazdan üstündür.", s: "İbn Mâce, Ahmed b. Hanbel" },
{ t: "Mescidimde kılınan bir namaz, Mescid-i Haram hariç, başka mescitlerde kılınan bin namazdan daha faziletlidir.", s: "Buhârî, Müslim" },
{ t: "Üç mescit dışında yolculuğa çıkılmaz: Mescid-i Haram, benim mescidim ve Mescid-i Aksâ.", s: "Buhârî, Müslim" },
{ t: "Kurban gününde Âdemoğlunun Allah'a en sevimli ameli kan akıtmaktır; kurban kıyamet günü boynuzları ve tırnaklarıyla gelir.", s: "Tirmizî, İbn Mâce" },
{ t: "Gücü yettiği hâlde kurban kesmeyen kimse namazgâhımıza yaklaşmasın.", s: "İbn Mâce, Edâhî 2" },
{ t: "Kurbanınızı güzel kesin; bıçağınızı bileyin ve hayvanı rahat ettirin.", s: "Müslim, Sayd 57" },
{ t: "Kurban etlerinden yiyin, biriktirin ve sadaka verin.", s: "Buhârî, Müslim" },
{ t: "Bayram günleri yeme, içme ve Allah'ı zikretme günleridir.", s: "Müslim, Sıyâm 144" },
{ t: "Her toplumun bir bayramı vardır; bu da bizim bayramımızdır.", s: "Buhârî, Müslim" },
{ t: "Ramazan Bayramı namazına giderken bir şeyler yemeden çıkmazdı; Kurban Bayramı'nda ise namazdan dönünceye kadar yemezdi.", s: "Tirmizî, İbn Mâce" },
{ t: "Bayramda, bayram namazına bir yoldan gider başka yoldan dönerdi.", s: "Buhârî, Îdeyn 24" },
{ t: "Zilhicce'nin ilk on gününde yapılan salih amel, Allah'a diğer günlerde yapılandan daha sevimlidir.", s: "Buhârî, Îdeyn 11" },
{ t: "Allah'ım, malımızı ve ömrümüzü bereketli kıl; bize verdiğin rızka kanaat ver.", s: "Riyâzü's-Sâlihîn" },
{ t: "Bir hurma bile olsa sadaka vermekten geri durma; azıcık verilen sadaka çoğu doğurur.", s: "Riyâzü's-Sâlihîn" },
{ t: "Sadaka vermekte acele edin; belâ sadakayı geçemez.", s: "Beyhakî" },
{ t: "Az bir sadakayı, veren için önemsiz görmeyin; bir Müslümanın yüzünü güldürmek bile sadakadır.", s: "Riyâzü's-Sâlihîn" },
{ t: "Kişi malından yiyip tükettiğini ve giyip eskittiğini bırakır; verdiği sadaka ise kalıcıdır.", s: "Müslim, Zühd 3" },
{ t: "Kul ölünce ameli kesilir; ancak sadaka-i câriye, faydalanılan ilim ve kendisine dua eden salih evlat bunun dışındadır.", s: "Müslim, Vasiyyet 14" },
{ t: "Bir dirhem, yüz bin dirhemi geçmiştir: Biri iki dirhemi olup birini veren, diğeri çok malının bir kısmını veren.", s: "Nesâî, Zekât 49" },
{ t: "İnsanın kendi kazancından yemesi ve ailesine yedirmesi sadakadır.", s: "Riyâzü's-Sâlihîn" },
{ t: "Sadaka veren kimseye Allah, verdiğinin yerine daha hayırlısını verir.", s: "Riyâzü's-Sâlihîn" },
{ t: "Kim borçlu olana kolaylık gösterirse, Allah ona dünya ve ahirette kolaylık gösterir.", s: "Müslim, Zikir 38" },
{ t: "Kim darda olan borçluya mühlet verir veya alacağını bağışlarsa, Allah onu kıyamet gününün sıkıntısından korur.", s: "Müslim, Zühd 74" },
{ t: "Zengin kimsenin borcunu geciktirmesi zulümdür.", s: "Buhârî, Müslim" },
{ t: "Kişi, kardeşinin yardımında olduğu sürece Allah da onun yardımındadır; sadaka Allah'ın rızasını kazandırır.", s: "Riyâzü's-Sâlihîn" },
{ t: "Hiç kimse, Allah'ın kendisine verdiği maldan başkasına harcayarak fakir düşmez.", s: "Riyâzü's-Sâlihîn" },
{ t: "Kim bir yetimin başını okşarsa, elinin dokunduğu her saç teli için bir sevap yazılır.", s: "Ahmed b. Hanbel, Müsned" },
{ t: "Müslüman toplulukların en hayırlı evi, kendisinde iyilik gören bir yetimin bulunduğu evdir.", s: "İbn Mâce, Edeb 6" },
{ t: "Kim kardeşinin borcunu öderse, Allah kıyamet günü onun borcunu öder.", s: "Riyâzü's-Sâlihîn" },
{ t: "Ramazan'da cömertlikte, esen rüzgârdan daha cömert olurdu.", s: "Buhârî, Müslim" },
{ t: "Ramazan, sabır ayıdır; sabrın karşılığı ise cennettir. O, yardımlaşma ayıdır; müminin rızkının arttırıldığı aydır.", s: "İbn Huzeyme, Sahîh" },
{ t: "Ramazan'ın başı rahmet, ortası mağfiret, sonu cehennemden kurtuluştur.", s: "İbn Huzeyme, Sahîh" },
{ t: "Kim Ramazan'da bir oruçluya bir yudum su ya da bir hurma verirse Allah ona havzımdan içirir.", s: "İbn Huzeyme, Sahîh" },
{ t: "Oruç ve Kur'an kıyamet günü kula şefaat eder: Oruç 'onu yemekten alıkoydum, beni şefaatçi kıl' der; Kur'an 'onu uykudan alıkoydum' der. Böylece şefaat ederler.", s: "Ahmed b. Hanbel, Müsned" },
{ t: "Nice oruç tutan vardır ki orucundan ona sadece açlık kalır; nice gece namaz kılan vardır ki ona sadece uykusuzluk kalır.", s: "İbn Mâce, Sıyâm 21" },
{ t: "Sahurda olsun iftarda olsun, hurma müminin gıdasıdır; evinde hurma olan ev halkı aç kalmaz.", s: "Müslim, Eşribe 152" },
{ t: "Kim bir oruçluya iftar yemeği yedirirse, o oruçlunun sevabı kadar sevap alır, oruçlunun sevabından da bir şey eksilmez.", s: "Tirmizî, Savm 82" },
{ t: "Kim güzelce abdest alır, Ramazan'ın son on gecesinde ibadetle geceyi geçirirse Allah onu affeder.", s: "Riyâzü's-Sâlihîn" },

/* ── AHLÂK: DOĞRULUK, YALAN, GIYBET, ÖFKE, TEVAZU, KİBİR, HASET, SABIR, ŞÜKÜR, HAYÂ, AF ── */
{ t: "Doğruluk iyiliğe, iyilik cennete götürür. Kişi doğru söyleye söyleye Allah katında sıddîk yazılır. Yalan kötülüğe, kötülük cehenneme götürür. Kişi yalan söyleye söyleye Allah katında yalancı yazılır.", s: "Buhârî, Müslim" },
{ t: "Kendisine emanet edilen şeye hıyanet edende iman yoktur; ahdine vefa göstermeyenin dini yoktur.", s: "Ahmed b. Hanbel, Müsned" },
{ t: "Şakadan bile olsa yalan söylemeyi bırakana cennetin ortasında bir köşk garanti ederim.", s: "Ebû Dâvûd, Edeb 7" },
{ t: "İnsanları güldürmek için yalan söyleyene yazıklar olsun, yazıklar olsun, yazıklar olsun.", s: "Ebû Dâvûd, Tirmizî" },
{ t: "Gıybet, kardeşini hoşlanmayacağı bir şeyle anmandır. Söylediğin onda varsa gıybet etmiş olursun; yoksa iftira etmiş olursun.", s: "Müslim, Birr 70" },
{ t: "Kıyamet günü kişinin mizanında güzel ahlâktan daha ağır bir şey yoktur.", s: "Ebû Dâvûd, Tirmizî" },
{ t: "Ben ancak güzel ahlâkı tamamlamak için gönderildim.", s: "Muvatta, Ahmed b. Hanbel" },
{ t: "Öfkelenme! (Bunu birkaç kez tekrarladı.)", s: "Buhârî, Edeb 76" },
{ t: "Öfke şeytandandır, şeytan ateşten yaratıldı; ateş suyla söner. Biriniz öfkelenince abdest alsın.", s: "Ebû Dâvûd, Edeb 3" },
{ t: "Biriniz ayakta iken öfkelenirse otursun; öfkesi geçmezse yatsın.", s: "Ebû Dâvûd, Edeb 3" },
{ t: "Kim öfkesini uygulamaya gücü yeterken yutarsa, Allah kıyamet günü onu bütün mahlûkatın önünde çağırır ve hurilerden dilediğini seçtirir.", s: "Ebû Dâvûd, Tirmizî" },
{ t: "Bir kimsenin öfkesini yutması kadar Allah katında büyük bir yudum yoktur.", s: "İbn Mâce, Zühd 18" },
{ t: "Sabır, ilk darbe anındadır.", s: "Buhârî, Müslim" },
{ t: "Sabır aydınlıktır.", s: "Müslim, Tahâret 1" },
{ t: "Kimseye sabırdan daha hayırlı ve geniş bir nimet verilmemiştir.", s: "Buhârî, Müslim" },
{ t: "Allah bir kula bir belâ verir de o sabrederse, Allah ona cenneti verir.", s: "Riyâzü's-Sâlihîn" },
{ t: "Müslümana gelen her yorgunluk, hastalık, tasa, keder, eziyet ve gam; hatta batan bir diken bile, Allah'ın onun günahlarını bağışlamasına vesile olur.", s: "Buhârî, Müslim" },
{ t: "Allah kimin hayrını dilerse onu musibete uğratır.", s: "Buhârî, Merdâ 1" },
{ t: "Cennete zorluklarla, cehenneme şehvetlerle ulaşılır.", s: "Buhârî, Müslim" },
{ t: "İnsanlara teşekkür etmeyen Allah'a şükretmez.", s: "Ebû Dâvûd, Tirmizî" },
{ t: "Size bir iyilik yapana karşılık verin; verecek bir şey bulamazsanız, karşılık verdiğinize inanıncaya kadar ona dua edin.", s: "Ebû Dâvûd, Nesâî" },
{ t: "Kendisine iyilik yapılan kimse iyilik yapana 'Cezâkellâhu hayran' derse, ona en güzel şekilde teşekkür etmiş olur.", s: "Tirmizî, Birr 87" },
{ t: "Sizden aşağıda olanlara bakın, üstünüzde olanlara bakmayın. Bu, Allah'ın nimetini küçümsememeniz için daha uygundur.", s: "Buhârî, Müslim" },
{ t: "Hayâ tamamen hayırdır.", s: "Müslim, Îmân 61" },
{ t: "Hayâ ancak hayır getirir.", s: "Buhârî, Müslim" },
{ t: "Utanmadıktan sonra dilediğini yap.", s: "Buhârî, Enbiyâ 54" },
{ t: "Hayâ ve iman birbirinin arkadaşıdır; biri kalkınca diğeri de kalkar.", s: "Hâkim, el-Müstedrek" },
{ t: "Her dinin bir ahlâkı vardır; İslâm'ın ahlâkı hayâdır.", s: "İbn Mâce, Zühd 17" },
{ t: "Kim Allah için alçak gönüllü olursa Allah onu yükseltir; kim büyüklenirse Allah onu alçaltır.", s: "Müslim, Birr 69" },
{ t: "Allah bana birbirinize alçak gönüllü davranmanızı vahyetti; kimse kimseye böbürlenmesin, kimse kimseye zulmetmesin.", s: "Müslim, Cennet 64" },
{ t: "Kibir, hakkı kabul etmemek ve insanları küçük görmektir.", s: "Müslim, Îmân 147" },
{ t: "Elbisesini kibirle yerde sürüyene Allah kıyamet günü bakmaz.", s: "Buhârî, Müslim" },
{ t: "Kimse ölümü temenni etmesin; iyi ise belki iyiliğini artırır, kötü ise belki tövbe eder.", s: "Buhârî, Müslim" },
{ t: "Hasetten sakının; ateşin odunu yediği gibi haset de iyilikleri yer.", s: "Ebû Dâvûd, Edeb 44" },
{ t: "Birbirinize haset etmeyin, birbirinize sırt çevirmeyin, birbirinize kin tutmayın. Ey Allah'ın kulları, kardeş olun!", s: "Buhârî, Müslim" },
{ t: "Bir Müslümanın kardeşine üç günden fazla küs durması helâl değildir. En hayırlıları önce selâm verendir.", s: "Buhârî, Müslim" },
{ t: "Zandan sakının; zan sözün en yalanıdır. Kusur araştırmayın, casusluk yapmayın, kıskanmayın.", s: "Buhârî, Müslim" },
{ t: "Söz taşıyan (koğucu) cennete giremez.", s: "Buhârî, Müslim" },
{ t: "Müslümana sövmek fâsıklık, onunla savaşmak küfürdür.", s: "Buhârî, Müslim" },
{ t: "Mümin; ayıplayıcı, lânet edici, çirkin ve hayâsız söz söyleyen kimse değildir.", s: "Tirmizî, Birr 48" },
{ t: "Lânet etmeyi âdet edinenler kıyamet günü ne şefaatçi ne şahit olabilirler.", s: "Müslim, Birr 85" },
{ t: "Bir kimse arkadaşına 'Ey kâfir' derse, bu ikisinden birine döner.", s: "Buhârî, Müslim" },
{ t: "Birbirine sırt çevirmeyin, kin tutmayın, haset etmeyin; Allah'ın kulları kardeş olun.", s: "Müslim, Birr 23" },
{ t: "Bir kimsenin kendine yapılan iyiliği başa kakması, sadakasını iptal eder.", s: "Riyâzü's-Sâlihîn" },
{ t: "Kim bir Müslümanı korkutursa Allah onu korkutur.", s: "Riyâzü's-Sâlihîn" },
{ t: "Kişinin çok konuşması ayıbını açığa çıkarır; sükût eden kurtulur.", s: "Tirmizî, Sıfatü'l-Kıyâme 50" },
{ t: "Susan kurtulmuştur.", s: "Tirmizî, Ahmed b. Hanbel" },
{ t: "Kişi, önemsemeden söylediği bir sözle cehennemde yetmiş yıl aşağı yuvarlanır.", s: "Tirmizî, Zühd 10" },
{ t: "Kul Allah'ın rızasına uygun bir söz söyler, önemsemez; ama Allah onunla derecesini yükseltir. Kul Allah'ın gazabına uygun bir söz söyler, önemsemez; ama onunla cehenneme düşer.", s: "Buhârî, Rikâk 23" },
{ t: "Dilini tut, evin sana yetsin, hatalarına ağla.", s: "Tirmizî, Zühd 61" },
{ t: "Sizden biriniz, kardeşinin gözündeki çöpü görür de kendi gözündeki merteği görmez.", s: "Riyâzü's-Sâlihîn" },
{ t: "Ne mutlu, kendi ayıbıyla meşgul olup başkalarının ayıbını görmeyen kimseye!", s: "Bezzâr, Müsned" },
{ t: "Kimseyi kınamayın; kınadığınız şey başınıza gelmeden ölmezsiniz.", s: "Tirmizî, Sıfatü'l-Kıyâme 53" },
{ t: "Kişi kardeşini bir günahla ayıplarsa, o günahı işlemeden ölmez.", s: "Tirmizî, Sıfatü'l-Kıyâme 53" },
{ t: "Mümin kardeşini hafife almak, kişiye kötülük olarak yeter.", s: "Müslim, Birr 32" },
{ t: "Bir kimsenin başkasıyla alay etmesi, ona zulümdür; Müslümanın malı, canı ve namusu diğer Müslümana haramdır.", s: "Müslim, Birr 32" },
{ t: "Yumuşaklık nerede bulunursa orayı güzelleştirir; nereden çekilirse orayı çirkinleştirir.", s: "Müslim, Birr 78" },
{ t: "Allah yumuşaktır, yumuşaklığı sever; sertliğe ve başka hiçbir şeye vermediğini yumuşaklığa verir.", s: "Müslim, Birr 77" },
{ t: "Yumuşaklıktan mahrum olan hayırdan mahrum olur.", s: "Müslim, Birr 74" },
{ t: "Cehenneme haram olan kimseyi size haber vereyim mi? İnsanlara yakın, yumuşak huylu, kolaylık gösteren kimse.", s: "Tirmizî, Sıfatü'l-Kıyâme 45" },
{ t: "İnsanların en hayırlısı, ömrü uzun ve ameli güzel olandır; en kötüsü ömrü uzun ve ameli kötü olandır.", s: "Tirmizî, Zühd 21" },
{ t: "Kim bir kavme benzemeye çalışırsa o da onlardandır.", s: "Ebû Dâvûd, Libâs 4" },
{ t: "Affedin ki affedilesiniz.", s: "Riyâzü's-Sâlihîn" },
{ t: "Mazlumun duasından sakın; onunla Allah arasında perde yoktur.", s: "Buhârî, Müslim" },
{ t: "Zulümden sakının; zulüm kıyamet günü karanlıklardır.", s: "Müslim, Birr 56" },
{ t: "Kimin üzerinde kardeşinin bir hakkı varsa, dinar ve dirhemin olmadığı gün gelmeden onunla helâlleşsin.", s: "Buhârî, Mezâlim 10" },
{ t: "Müflis kimdir bilir misiniz? Kıyamet günü namaz, oruç, zekâtla gelir; ama şuna sövmüş, buna iftira etmiş, şunun malını yemiş… İyilikleri onlara dağıtılır, bitince onların günahları ona yüklenir ve ateşe atılır.", s: "Müslim, Birr 59" },
{ t: "Allah, kardeşine yardım eden kuluna yardım eder; affeden kulunun izzetini artırır.", s: "Müslim, Birr 69" },
{ t: "Kötülüğe iyilikle karşılık ver; kötülüğü iyilik giderir.", s: "Riyâzü's-Sâlihîn" },
{ t: "Kim bağışlar ve barışırsa, onun mükâfatı Allah'a aittir.", s: "Riyâzü's-Sâlihîn" },
{ t: "Sıla-i rahim, sadece iyiliğe iyilikle karşılık vermek değildir; asıl sıla, akrabası ilişkiyi kestiğinde onunla ilişkiyi sürdürendir.", s: "Buhârî, Edeb 15" },
{ t: "Sizden biriniz mümin kardeşi hakkında konuşurken, onun yüzüne söyleyemeyeceği şeyi arkasından da söylemesin.", s: "Riyâzü's-Sâlihîn" },
{ t: "Bir kimse, kardeşinin gıyabında ırzını korursa, Allah kıyamet günü onun yüzünü ateşten korur.", s: "Tirmizî, Birr 20" },
{ t: "Sözün en doğrusu Allah'ın Kitabı'dır; yolların en güzeli Muhammed'in yoludur.", s: "Müslim, Cum'a 43" },
{ t: "Hikmetli söz müminin yitiğidir; nerede bulursa alsın.", s: "Tirmizî, İlim 19" },
{ t: "İnsanlara güç yetiremeyecekleri yükü yüklemeyin.", s: "Riyâzü's-Sâlihîn" },
{ t: "Kişinin dosdoğru olması, dilinin doğru olmasıyla; dilinin doğru olması ise kalbinin doğru olmasıyla mümkündür.", s: "Ahmed b. Hanbel, Müsned" },
{ t: "İman, kalpte tasdik, dilde ikrar, organlarla ameldir.", s: "İbn Mâce, Mukaddime 9" },
{ t: "Az konuşan, çok iş yapan kimse hayırlıdır.", s: "Riyâzü's-Sâlihîn" },
{ t: "Söz veren sözünde dursun; vefa imandandır.", s: "Riyâzü's-Sâlihîn" },
{ t: "Bir şey vaat ettiğinde onu yerine getir; vaadi bozmak münafıklık alâmetidir.", s: "Riyâzü's-Sâlihîn" },
{ t: "Kim bir kavme ihanet ederse, kıyamet günü ihanetinin bayrağı arkasında dikilir.", s: "Buhârî, Müslim" },
{ t: "Emaneti sana emanet edene ver; sana ihanet edene sen ihanet etme.", s: "Ebû Dâvûd, Tirmizî" },
{ t: "Meclisler emanettir; üç meclis hariç: Haram kan dökmek, zina etmek veya haksız yere mal almak için yapılan meclisler.", s: "Ebû Dâvûd, Edeb 32" },
{ t: "Sizden biri kardeşinin yerine bir sözü nakleder de onun için istemediği bir şeye sebep olursa, ona ihanet etmiştir.", s: "Riyâzü's-Sâlihîn" },
{ t: "İki kişi fısıldaşırken üçüncüyü dışlamayın; bu onu üzer.", s: "Buhârî, Müslim" },
{ t: "Kim bir kavmin izni olmadan sözlerini dinlerse, kıyamet günü kulaklarına kurşun dökülür.", s: "Buhârî, Ta'bîr 45" },
{ t: "Bir topluluk içinde oturan biri kalkarken 'Sübhânekellâhümme ve bihamdike, eşhedü en lâ ilâhe illâ ente, estağfiruke ve etûbü ileyk' derse, o meclisteki hataları bağışlanır.", s: "Ebû Dâvûd, Tirmizî" },
{ t: "İyi ve kötü arkadaşın misali, misk taşıyan ile körük çeken gibidir: Misk taşıyan ya sana verir ya satar ya da güzel koku alırsın; körük çeken ya elbiseni yakar ya da kötü koku alırsın.", s: "Buhârî, Müslim" },
{ t: "İnsanlardan bir kısmı hayrın anahtarı, şerrin kilididir; bir kısmı şerrin anahtarı, hayrın kilididir. Ne mutlu Allah'ın hayrın anahtarını eline verdiği kimseye!", s: "İbn Mâce, Mukaddime 19" },
{ t: "Cömert Allah'a, cennete ve insanlara yakın; cehenneme uzaktır. Cimri ise Allah'a, cennete ve insanlara uzak; cehenneme yakındır.", s: "Tirmizî, Birr 40" },
{ t: "Cimrilikten sakının; cimrilik sizden öncekileri helâk etti.", s: "Müslim, Birr 56" },
{ t: "İki haslet müminde bir araya gelmez: Cimrilik ve kötü ahlâk.", s: "Tirmizî, Birr 41" },
{ t: "Kanaat tükenmez bir hazinedir.", s: "Beyhakî, Şuabü'l-Îmân" },
{ t: "Beden sağlığı ve kalp huzuru verilen kimse, dünya kendisine verilmiş gibidir.", s: "Tirmizî, Zühd 34" },
{ t: "Kim kötü sözü ve kötü fiili bırakmazsa, Allah'ın onun aç ve susuz kalmasına ihtiyacı yoktur.", s: "Buhârî, Savm 8" },
{ t: "Sizin en hayırlınız, insanlara en faydalı olan ve en güzel ahlâklı olanınızdır.", s: "Riyâzü's-Sâlihîn" },
{ t: "İnsanların en kötüsü, bir yüzle bunlara, başka yüzle onlara giden iki yüzlü kimsedir.", s: "Buhârî, Müslim" },
{ t: "Bir kimse için, kendine söylenen her şeyi anlatması, yalan olarak yeter.", s: "Müslim, Mukaddime 5" },
{ t: "Kalbi temiz olan, dili doğru olan mümin kimsedir; hıyanet eden, yalan söyleyen kimse değil.", s: "Riyâzü's-Sâlihîn" },
{ t: "İnsan, dostuna zulmetmez; onu yalnız bırakmaz; onu küçük görmez.", s: "Riyâzü's-Sâlihîn" },
{ t: "Sizden biri kardeşinin, hoşuna gitmeyen bir şeyini görürse ona nasihat etsin; gıybetini etmesin.", s: "Riyâzü's-Sâlihîn" },
{ t: "Sabreden zafere ulaşır; şükreden nimetini artırır.", s: "Riyâzü's-Sâlihîn" },
{ t: "Kim şükretmezse nimeti kaybeder; kim sabretmezse belâdan kurtulmaz.", s: "Riyâzü's-Sâlihîn" },
{ t: "Sana verilene razı ol ki insanların en zengini olasın.", s: "Tirmizî, Zühd 35" },
{ t: "Dünyada garip ya da yolcu gibi ol.", s: "Buhârî, Rikâk 3" },
{ t: "Akşama ulaştığında sabahı bekleme; sabaha ulaştığında akşamı bekleme. Sağlığında hastalığın için, hayatında ölümün için hazırlık yap.", s: "Buhârî, Rikâk 3" },
{ t: "Beş şeyden önce beş şeyin kıymetini bil: İhtiyarlıktan önce gençliğin, hastalıktan önce sağlığın, fakirlikten önce zenginliğin, meşguliyetten önce boş vaktin, ölümden önce hayatın.", s: "Hâkim, el-Müstedrek" },
{ t: "İki nimet vardır ki insanların çoğu bunda aldanmıştır: Sağlık ve boş vakit.", s: "Buhârî, Rikâk 1" },
{ t: "Kıyamet günü kul, dört şeyden sorulmadan yerinden ayrılamaz: Ömrünü nerede tükettiğinden, ilmiyle ne yaptığından, malını nereden kazanıp nereye harcadığından, bedenini nerede yıprattığından.", s: "Tirmizî, Sıfatü'l-Kıyâme 1" },
{ t: "Akıllı kimse nefsini hesaba çeken ve ölümden sonrası için çalışandır. Âciz ise nefsini hevâsına uydurup Allah'tan boş temennide bulunandır.", s: "Tirmizî, Sıfatü'l-Kıyâme 25" },
{ t: "Hesaba çekilmeden önce kendinizi hesaba çekin; tartılmadan önce kendinizi tartın.", s: "Tirmizî" },
{ t: "İnsanların en akıllısı ölümü en çok hatırlayan ve ona en iyi hazırlanandır.", s: "İbn Mâce, Zühd 31" },
{ t: "Lezzetleri kesen ölümü çok anın.", s: "Tirmizî, Nesâî" },
{ t: "Öfke imanı bozar; sirkenin balı bozduğu gibi.", s: "Beyhakî" },
{ t: "Hilm (yumuşak başlılık) ve teennî Allah'ın sevdiği iki haslettir.", s: "Müslim, Îmân 25" },
{ t: "Kim insanlara merhamet etmezse Allah da ona merhamet etmez.", s: "Buhârî, Müslim" },
{ t: "Sizden önce bir adam, kolaylaştırdığı için bağışlandı: Zengine kolaylık gösterir, fakire mühlet verirdi.", s: "Buhârî, Müslim" },
{ t: "Merhamet ancak şakî (bedbaht) kimseden alınır.", s: "Ebû Dâvûd, Tirmizî" },
{ t: "İnsanlar bir tarağın dişleri gibi eşittir; üstünlük ancak takvâ iledir.", s: "Riyâzü's-Sâlihîn" },
{ t: "Arabın Arap olmayana, Arap olmayanın Araba üstünlüğü yoktur; üstünlük ancak takvâ iledir.", s: "Ahmed b. Hanbel, Müsned" },
{ t: "Allah cahiliye gururunu ve atalarla övünmeyi kaldırmıştır. İnsanlar Âdem'dendir, Âdem de topraktan.", s: "Ebû Dâvûd, Tirmizî" },

/* ── AİLE, ANNE-BABA, AKRABA, KOMŞU, ÇOCUK, EVLİLİK, KADIN HAKLARI ── */
{ t: "Cennet annelerin ayakları altındadır.", s: "Nesâî, Cihâd 6" },
{ t: "Bir adam 'Ey Allah'ın Resûlü, kendisine en iyi davranmam gereken kimdir?' diye sordu. 'Annen' buyurdu. 'Sonra kim?' 'Annen.' 'Sonra kim?' 'Annen.' 'Sonra kim?' 'Baban' buyurdu.", s: "Buhârî, Müslim" },
{ t: "Rabbin rızası anne babanın rızasında, Rabbin gazabı anne babanın gazabındadır.", s: "Tirmizî, Birr 3" },
{ t: "Anne babasına iyi davranan kimseye ne mutlu! Allah onun ömrünü uzatır.", s: "Hâkim, el-Müstedrek" },
{ t: "Burnu sürtülsün, burnu sürtülsün, burnu sürtülsün! Anne babasından birine veya ikisine yaşlılıklarında yetişip de cennete giremeyen kimsenin.", s: "Müslim, Birr 9" },
{ t: "Baba cennetin orta kapısıdır; istersen o kapıyı koru, istersen bırak.", s: "Tirmizî, Birr 3" },
{ t: "Bir adam 'Anne babama iyilik ettim, öldüler; şimdi ne yapabilirim?' dedi. 'Onlara dua etmek, bağışlanmalarını dilemek, vasiyetlerini yerine getirmek, akrabalarını gözetmek, dostlarına ikram etmek' buyurdu.", s: "Ebû Dâvûd, Edeb 120" },
{ t: "Kişinin, babasının dostlarını gözetmesi iyiliklerin en üstünüdür.", s: "Müslim, Birr 11" },
{ t: "Anne babaya sövmek büyük günahlardandır. Bir kimse başkasının babasına söver, o da onun babasına söver; işte böylece kendi babasına sövmüş olur.", s: "Buhârî, Müslim" },
{ t: "Allah'a ortak koşmak, anne babaya karşı gelmek ve yalancı şahitlik büyük günahların en büyükleridir.", s: "Buhârî, Müslim" },
{ t: "Allah, dilediği günahı kıyamete erteler; ancak anne babaya isyan edenin cezasını sahibine daha hayattayken verir.", s: "Hâkim, el-Müstedrek" },
{ t: "Sıla-i rahim yapan (akrabayı gözeten) kimsenin rızkı bollaşır, ömrü uzar.", s: "Buhârî, Müslim" },
{ t: "Akraba ilişkisini kesen cennete giremez.", s: "Buhârî, Müslim" },
{ t: "Rahim (akrabalık) Arş'a asılıdır ve der ki: Beni gözeteni Allah gözetsin, beni koparanı Allah koparsın.", s: "Buhârî, Müslim" },
{ t: "Kim rızkının bollaşmasını ve ömrünün uzamasını isterse akrabasını gözetsin.", s: "Buhârî, Müslim" },
{ t: "Sizin en hayırlınız, ailesine karşı en hayırlı olanınızdır. Ben de aileme karşı en hayırlınızım.", s: "Tirmizî, Menâkıb 63" },
{ t: "Müminlerin iman bakımından en olgunu, ahlâkı en güzel olanıdır. Sizin en hayırlınız hanımlarına en iyi davrananınızdır.", s: "Tirmizî, Radâ' 11" },
{ t: "Kadınlar hakkında Allah'tan korkun; onları Allah'ın emaneti olarak aldınız.", s: "Müslim, Hac 147" },
{ t: "Kadınlara iyi davranın; onlar sizin yanınızda emanettir.", s: "Tirmizî, Radâ' 11" },
{ t: "Kadınlara hayırla muamele edin; kadın kaburga kemiğinden yaratılmıştır. Düzeltmeye kalkarsan kırarsın; olduğu gibi bırakırsan eğri kalır.", s: "Buhârî, Müslim" },
{ t: "Bir mümin erkek, mümin bir kadına buğzetmesin; bir huyunu beğenmezse başka bir huyunu beğenir.", s: "Müslim, Radâ' 61" },
{ t: "Dünya geçici bir metadır; dünya metaının en hayırlısı saliha kadındır.", s: "Müslim, Radâ' 64" },
{ t: "Kadın dört şey için nikâhlanır: Malı, soyu, güzelliği ve dini için. Sen dindar olanı seç ki elin bereket bulsun.", s: "Buhârî, Müslim" },
{ t: "Ey gençler! Evlenmeye gücü yeten evlensin; gücü yetmeyen oruç tutsun, oruç onun için kalkandır.", s: "Buhârî, Müslim" },
{ t: "Nikâh benim sünnetimdir; sünnetimden yüz çeviren benden değildir.", s: "İbn Mâce, Nikâh 1" },
{ t: "Nikâhın en bereketlisi, en kolay olanıdır.", s: "Ahmed b. Hanbel, Müsned" },
{ t: "Nikâhı ilan edin; mescitlerde kıyın; üzerine def çalın.", s: "Tirmizî, Nikâh 6" },
{ t: "Dini ve ahlâkı hoşnut olduğunuz biri size talip olursa onu evlendirin; yoksa yeryüzünde fitne ve büyük fesat olur.", s: "Tirmizî, Nikâh 3" },
{ t: "Biriniz bir kadınla evlenmek istediğinde, evlenmesine sebep olacak şeylerine bakabilir.", s: "Ebû Dâvûd, Nikâh 18" },
{ t: "Kişi ailesine harcadığından dolayı sevap alır.", s: "Buhârî, Müslim" },
{ t: "Kişi, ailesinin ağzına koyduğu lokmadan bile sevap kazanır.", s: "Buhârî, Müslim" },
{ t: "Kişinin, geçimini üstlendiği kimseleri ihmal etmesi günah olarak yeter.", s: "Ebû Dâvûd, Zekât 45" },
{ t: "Hepiniz çobansınız ve hepiniz sürünüzden sorumlusunuz. Yönetici çobandır; erkek ailesinin çobanıdır; kadın kocasının evinin çobanıdır.", s: "Buhârî, Müslim" },
{ t: "Kadın beş vaktini kılar, orucunu tutar, iffetini korur ve kocasına itaat ederse, cennetin dilediği kapısından girer.", s: "Ahmed b. Hanbel, Müsned" },
{ t: "En hayırlı kadın, baktığında seni sevindiren, emrettiğinde itaat eden, kendisi ve malı hakkında hoşlanmadığın bir şey yapmayandır.", s: "Nesâî, Nikâh 14" },
{ t: "Kocası kendisinden razı olarak ölen kadın cennete girer.", s: "Tirmizî, Radâ' 10" },
{ t: "Kim iki kız çocuğunu ergenlik çağına kadar büyütürse, kıyamet günü benimle beraber olur (parmaklarını birleştirdi).", s: "Müslim, Birr 149" },
{ t: "Kim kız çocuklarıyla imtihan edilir de onlara iyi davranırsa, onlar ateşe karşı perde olur.", s: "Buhârî, Müslim" },
{ t: "Kimin bir kızı olur da onu diri diri gömmez, hor görmez, oğlunu ona tercih etmezse Allah onu cennete koyar.", s: "Ebû Dâvûd, Edeb 120" },
{ t: "Çocuklarınıza ikram edin ve terbiyelerini güzel yapın.", s: "İbn Mâce, Edeb 3" },
{ t: "Çocuklarınıza adalet edin; hediye verirken aralarında eşit davranın.", s: "Buhârî, Müslim" },
{ t: "Çocuklarınıza yedi yaşındayken namazı emredin; on yaşında kılmazlarsa uyarın, yataklarını ayırın.", s: "Ebû Dâvûd, Salât 26" },
{ t: "Küçüklerimize merhamet etmeyen, büyüklerimize saygı göstermeyen bizden değildir.", s: "Tirmizî, Birr 15" },
{ t: "Bir kimse, çocuğuna verdiği güzel terbiyeden daha üstün bir hediye vermemiştir.", s: "Tirmizî, Birr 33" },
{ t: "Kişinin ölümünden sonra ona ulaşan iyilikler: Öğrettiği ilim, bıraktığı salih evlat, miras bıraktığı Kur'an, yaptırdığı mescit, yolcular için yaptığı ev, akıttığı su ve sağlıklı iken verdiği sadaka.", s: "İbn Mâce, Mukaddime 20" },
{ t: "Çocuklarınızı öpün; her öpücük için cennette bir derece verilir.", s: "Riyâzü's-Sâlihîn" },
{ t: "Bir adam çocuklarını öpmediğini söyleyince: 'Allah senin kalbinden merhameti çekip almışsa ben ne yapabilirim?' buyurdu.", s: "Buhârî, Müslim" },
{ t: "Torunlarını (Hasan ve Hüseyin'i) öpüyordu. Bir adam 'On çocuğum var, hiçbirini öpmedim' dedi. 'Merhamet etmeyene merhamet edilmez' buyurdu.", s: "Buhârî, Müslim" },
{ t: "Cebrail bana komşuyu o kadar tavsiye etti ki, onu mirasçı kılacağını zannettim.", s: "Buhârî, Müslim" },
{ t: "Vallahi iman etmiş olmaz, vallahi iman etmiş olmaz, vallahi iman etmiş olmaz! 'Kim ey Allah'ın Resûlü?' 'Komşusu kötülüklerinden emin olmayan kimse.'", s: "Buhârî, Müslim" },
{ t: "Komşusu, şerrinden emin olmayan kimse cennete giremez.", s: "Müslim, Îmân 73" },
{ t: "Sizden biriniz komşusunun duvarına kiriş koymasına engel olmasın.", s: "Buhârî, Müslim" },
{ t: "Ey Ebû Zer! Çorba pişirdiğinde suyunu çok koy ve komşularını gözet.", s: "Müslim, Birr 142" },
{ t: "Allah katında en hayırlı arkadaş, arkadaşına en hayırlı olandır; en hayırlı komşu, komşusuna en hayırlı olandır.", s: "Tirmizî, Birr 28" },
{ t: "Komşusuna eziyet eden bana eziyet etmiştir; bana eziyet eden Allah'a eziyet etmiştir.", s: "Riyâzü's-Sâlihîn" },
{ t: "Bir kimse kapısını komşusuna kapatırsa Allah da rahmet kapısını ona kapatır.", s: "Riyâzü's-Sâlihîn" },
{ t: "Ey kadınlar! Komşunuz size koyun paçası bile hediye etse hor görmeyin.", s: "Buhârî, Müslim" },
{ t: "Hediyeleşin; hediye kalpteki kini giderir ve sevgiyi artırır.", s: "Tirmizî, Velâ 6" },
{ t: "Bana bir paça hediye edilse kabul ederim; bir davet olsa giderim.", s: "Buhârî, Hibe 2" },
{ t: "Ev halkının rızkını genişletmek için sadaka verin; verdiğinizin karşılığı size gelir.", s: "Riyâzü's-Sâlihîn" },
{ t: "Kişi hanımının ağzına verdiği lokma için sevap alır.", s: "Buhârî, Müslim" },
{ t: "Sizden biriniz hanımını köle döver gibi dövmesin; sonra da gün sonunda onunla yatağa girmesin.", s: "Buhârî, Müslim" },
{ t: "Kadınları dövenler sizin hayırlılarınız değildir.", s: "Ebû Dâvûd, Nikâh 43" },
{ t: "Allah'ın helâl kıldıkları içinde en sevmediği şey boşanmadır.", s: "Ebû Dâvûd, Talâk 3" },
{ t: "Bir kadın, sıkıntı olmadan kocasından boşanmak isterse cennetin kokusu ona haram olur.", s: "Ebû Dâvûd, Tirmizî" },
{ t: "Kim evlenirse dininin yarısını tamamlamış olur; kalan yarısı için Allah'tan korksun.", s: "Beyhakî, Şuabü'l-Îmân" },
{ t: "Yeni doğan çocuğun sağ kulağına ezan okurdu.", s: "Ebû Dâvûd, Tirmizî" },
{ t: "Her çocuk akikasıyla rehindir; yedinci gün kesilir, adı konur, başı tıraş edilir.", s: "Ebû Dâvûd, Tirmizî" },
{ t: "Çocuklarınıza güzel isim koyun; kıyamet günü kendi adınız ve babalarınızın adıyla çağrılırsınız.", s: "Ebû Dâvûd, Edeb 61" },
{ t: "Bir kadın, yanında mahremi olmadan bir günlük yola tek başına çıkmasın.", s: "Buhârî, Müslim" },
{ t: "Bir erkek, yanında mahremi olmayan bir kadınla baş başa kalmasın; üçüncüleri şeytandır.", s: "Tirmizî, Radâ' 16" },
{ t: "Gözlerin zinası bakmak, kulakların zinası dinlemek, dilin zinası konuşmak, elin zinası tutmak, ayağın zinası yürümektir.", s: "Buhârî, Müslim" },
{ t: "Bakışı bakışa ekleme; birincisi senin, ikincisi aleyhinedir.", s: "Ebû Dâvûd, Tirmizî" },
{ t: "Kadın kocasının evinde çobandır; ondan sorumludur.", s: "Buhârî, Müslim" },
{ t: "Sizden biriniz, eşinin sırrını başkalarına anlatmasın; bu, kıyamet günü Allah katında en kötü emanetlerdendir.", s: "Müslim, Nikâh 123" },
{ t: "Zevce, kocası yanında iken onun izni olmadan nafile oruç tutmasın.", s: "Buhârî, Müslim" },
{ t: "Kişi ailesine yumuşak davransın; Allah yumuşaklığı sever.", s: "Riyâzü's-Sâlihîn" },
{ t: "Bir kadına, kocasının izni olmadan evine kimseyi almaması gerekir.", s: "Buhârî, Müslim" },
{ t: "Evine girdiğinde selâm ver; selâm hem sana hem ev halkına berekettir.", s: "Tirmizî, İstizân 10" },
{ t: "Sizden biriniz evine girerken 'Bismillah' derse, şeytan 'Burada gecelemek yok' der; yemek yerken 'Bismillah' derse 'Yemek de yok' der.", s: "Müslim, Eşribe 103" },
{ t: "Kızkardeşin evli olsun olmasın, ona sıla yap; annen olduğu gibi kızkardeşin de senin üzerinde hak sahibidir.", s: "Riyâzü's-Sâlihîn" },
{ t: "Teyze anne makamındadır.", s: "Buhârî, Tirmizî" },
{ t: "Kişinin amcası, babası yerindedir.", s: "Riyâzü's-Sâlihîn" },
{ t: "Kim üç kız kardeş veya üç kızını geçindirir, terbiye edip evlendirirse ona cennet vardır.", s: "Ebû Dâvûd, Tirmizî" },
{ t: "Çocuğun babası üzerindeki hakkı: Ona güzel isim vermesi, güzel terbiye etmesi ve vakti gelince evlendirmesidir.", s: "Beyhakî" },
{ t: "Sizden biriniz ailesiyle şakalaşsın, onlara yumuşak davransın; ben ailemle şakalaşırım.", s: "Riyâzü's-Sâlihîn" },
{ t: "Çocuklara selâm verirdi; onlarla ilgilenir, hâllerini sorardı.", s: "Buhârî, Müslim" },
{ t: "Bir çocuğa 'Gel sana şunu vereyim' deyip vermezsen bu yalan yazılır.", s: "Ebû Dâvûd, Edeb 80" },
{ t: "Torunlarımın (Hasan ve Hüseyin'in) kokusunu koklardı; 'Onlar benim dünyadaki iki reyhanım' derdi.", s: "Buhârî, Tirmizî" },
{ t: "Eşine sabreden kadına Allah, Firavun'un karısı Âsiye'nin sevabı gibi sevap verir.", s: "Riyâzü's-Sâlihîn" },
{ t: "Kocasına sabreden ve iffetini koruyan kadın, mücahid gibidir.", s: "Riyâzü's-Sâlihîn" },
{ t: "Kadınların en hayırlısı, kocasına en yumuşak davranan, çocuklarına en şefkatli olan ve iffetini koruyandır.", s: "Riyâzü's-Sâlihîn" },
{ t: "Eşler arasındaki en güzel şey, birbirlerine merhamet ve muhabbetle bakmalarıdır.", s: "Riyâzü's-Sâlihîn" },
{ t: "Ana babana iyilik et ki çocukların da sana iyilik etsin.", s: "Taberânî" },
{ t: "İhtiyarlara saygı gösteren, gençliğinde ona saygı gösterecek birini bulur.", s: "Tirmizî, Birr 75" },
{ t: "Yaşlı Müslümana ikram etmek, Allah'a saygıdandır.", s: "Ebû Dâvûd, Edeb 20" },
{ t: "Bir gencin bir yaşlıya yaşından dolayı ikram etmesi karşılığında Allah, ona da yaşlandığında ikram edecek birini gönderir.", s: "Tirmizî, Birr 75" },
{ t: "Bize karşı şefkatli ol; küçüklerimize merhamet, büyüklerimize hürmet göster.", s: "Riyâzü's-Sâlihîn" },
{ t: "Evde yaşlı anne babası olan kimse, cihat sevabına ancak onlara hizmetle erer.", s: "Riyâzü's-Sâlihîn" },
{ t: "Bir adam cihada gitmek için izin istedi. 'Annen baban sağ mı?' 'Evet.' 'Onlara hizmet ederek cihat et' buyurdu.", s: "Buhârî, Müslim" },
{ t: "Bir adam: 'Annem çok yaşlandı, sırtımda taşıyorum; hakkını ödedim mi?' diye sordu. 'Doğum sancılarından bir tanesini bile ödemedin' buyurdu.", s: "Riyâzü's-Sâlihîn" },
{ t: "Kim anne babasının kabrini cuma günü ziyaret ederse bağışlanır ve hayırlı evlat yazılır.", s: "Beyhakî" },
{ t: "Sizden biriniz Ramazan'da ailesine ve akrabalarına daha çok iyilik etsin; Ramazan yakınlık ayıdır.", s: "Riyâzü's-Sâlihîn" },

/* ── İLİM, KUR'AN, ZİKİR, DUA, TÖVBE, İSTİĞFAR, SALAVAT ── */
{ t: "İlim öğrenmek her Müslümana farzdır.", s: "İbn Mâce, Mukaddime 17" },
{ t: "Âlimler peygamberlerin vârisleridir. Peygamberler dinar ve dirhem bırakmamış, ilim bırakmışlardır; onu alan büyük bir pay almıştır.", s: "Ebû Dâvûd, Tirmizî" },
{ t: "Âlimin âbide üstünlüğü, ayın diğer yıldızlara üstünlüğü gibidir.", s: "Ebû Dâvûd, Tirmizî" },
{ t: "Allah, ilim öğrenmek için yola çıkan kimseye cennete giden yolu kolaylaştırır. Melekler ilim talebesinden hoşnut olarak kanatlarını onun üzerine gererler.", s: "Ebû Dâvûd, Tirmizî" },
{ t: "Allah, ilmi insanlardan söküp almaz; âlimleri alarak ilmi alır. Âlim kalmayınca insanlar cahilleri baş edinir; onlar bilmeden fetva verir, hem saparlar hem saptırırlar.", s: "Buhârî, Müslim" },
{ t: "Bir kimsenin bir saat ilim öğrenmesi, bütün gece namaz kılmasından hayırlıdır.", s: "Riyâzü's-Sâlihîn" },
{ t: "Kim bir ilim öğrenir de onu gizlerse kıyamet günü ateşten bir gem vurulur.", s: "Ebû Dâvûd, Tirmizî" },
{ t: "Ancak iki kişiye gıpta edilir: Allah'ın mal verdiği ve onu hak yolunda harcamaya muvaffak kıldığı kimse; Allah'ın hikmet verdiği ve onunla hükmedip öğreten kimse.", s: "Buhârî, Müslim" },
{ t: "İlim öğrenin; ilim öğrenmek Allah korkusudur, onu aramak ibadettir, müzakere etmek tesbihtir.", s: "Riyâzü's-Sâlihîn" },
{ t: "Rabbim, ilmimi artır de.", s: "Tirmizî, Deavât 128" },
{ t: "Allah'ım! Bana öğrettiğinle beni faydalandır, bana fayda verecek şeyi öğret, ilmimi artır.", s: "Tirmizî, Deavât 128" },
{ t: "Allah'ım! Fayda vermeyen ilimden, huşû duymayan kalpten, doymayan nefisten ve kabul olunmayan duadan sana sığınırım.", s: "Müslim, Zikir 73" },
{ t: "Sizin en hayırlınız Kur'an'ı öğrenen ve öğretendir.", s: "Buhârî, Fedâilü'l-Kur'ân 21" },
{ t: "Kur'an okuyan mümin, kokusu ve tadı güzel olan turunç gibidir; Kur'an okumayan mümin, tadı güzel ama kokusu olmayan hurma gibidir.", s: "Buhârî, Müslim" },
{ t: "Kur'an'ı ustaca okuyan, şerefli ve itaatkâr meleklerle beraberdir. Zorlanarak, kekeleyerek okuyana ise iki kat sevap vardır.", s: "Buhârî, Müslim" },
{ t: "Kur'an'dan bir harf okuyana bir sevap vardır; her sevap on katıyla yazılır. 'Elif lâm mîm' bir harf demiyorum; elif bir harf, lâm bir harf, mîm bir harftir.", s: "Tirmizî, Fedâilü'l-Kur'ân 16" },
{ t: "Kur'an okuyun; o kıyamet günü sahiplerine şefaatçi olarak gelir.", s: "Müslim, Müsâfirîn 252" },
{ t: "Kalbinde Kur'an'dan bir şey bulunmayan kimse harap ev gibidir.", s: "Tirmizî, Fedâilü'l-Kur'ân 18" },
{ t: "Kur'an'ı ezberleyip sonra unutmak büyük günahlardandır.", s: "Ebû Dâvûd, Tirmizî" },
{ t: "Kur'an'ı gözden geçirip tekrar edin; o, sahibinden, devenin ipinden kurtulmasından daha hızlı kaçar.", s: "Buhârî, Müslim" },
{ t: "Kıyamet günü Kur'an ehline 'Oku ve yüksel; dünyada okuduğun gibi ağır ağır oku; menzilin okuduğun son ayetin yanındadır' denir.", s: "Ebû Dâvûd, Tirmizî" },
{ t: "Kur'an'ı sesinizle süsleyin.", s: "Ebû Dâvûd, Nesâî" },
{ t: "Kur'an'ı güzel sesle okumayan bizden değildir.", s: "Buhârî, Tevhîd 44" },
{ t: "Fatiha, dertlere şifadır.", s: "Dârimî" },
{ t: "Fatiha her derde devadır.", s: "Beyhakî" },
{ t: "Bakara sûresini okuyun; onu almak bereket, terk etmek hasrettir. Sihirbazlar ona güç yetiremez.", s: "Müslim, Müsâfirîn 252" },
{ t: "İçinde Bakara sûresi okunan evden şeytan kaçar.", s: "Müslim, Müsâfirîn 212" },
{ t: "Bakara sûresinin son iki âyetini geceleyin okuyan kimseye o iki âyet yeter.", s: "Buhârî, Müslim" },
{ t: "Kur'an'daki en büyük âyet Âyetü'l-Kürsî'dir.", s: "Müslim, Müsâfirîn 258" },
{ t: "Yatağa girdiğinde Âyetü'l-Kürsî'yi oku; Allah tarafından bir koruyucu seninle olur, sabaha kadar şeytan sana yaklaşamaz.", s: "Buhârî, Vekâle 10" },
{ t: "İhlâs sûresi Kur'an'ın üçte birine denktir.", s: "Buhârî, Müslim" },
{ t: "Sabah akşam üç defa İhlâs, Felak ve Nâs sûrelerini oku; her şeye karşı sana yeter.", s: "Ebû Dâvûd, Tirmizî" },
{ t: "Her gece Mülk sûresini okuyan kimseyi Allah kabir azabından korur.", s: "Tirmizî, Nesâî" },
{ t: "Kim Yasin'i Allah rızası için okursa geçmiş günahları bağışlanır; onu ölülerinizin yanında okuyun.", s: "Ebû Dâvûd, İbn Mâce" },
{ t: "Her şeyin bir kalbi vardır; Kur'an'ın kalbi Yasin'dir.", s: "Tirmizî, Fedâilü'l-Kur'ân 7" },
{ t: "Kim Kehf sûresinin ilk on âyetini ezberlerse Deccal'den korunur.", s: "Müslim, Müsâfirîn 257" },
{ t: "Kim cuma günü Kehf sûresini okursa iki cuma arasında nur ile aydınlanır.", s: "Hâkim, Beyhakî" },
{ t: "Kim geceleyin Vâkıa sûresini okursa fakirliğe düşmez.", s: "Beyhakî, Şuabü'l-Îmân" },
{ t: "Kim her namazın ardından Âyetü'l-Kürsî'yi okursa cennete girmesine ölümden başka engel kalmaz.", s: "Nesâî, Taberânî" },
{ t: "Zikrin en faziletlisi 'Lâ ilâhe illallah', duanın en faziletlisi 'Elhamdülillah'tır.", s: "Tirmizî, Deavât 9" },
{ t: "İki kelime vardır ki dile hafif, mizanda ağır, Rahmân'a sevimlidir: Sübhânallahi ve bihamdihî, sübhânallahi'l-azîm.", s: "Buhârî, Müslim" },
{ t: "Kim günde yüz defa 'Sübhânallahi ve bihamdihî' derse, günahları deniz köpüğü kadar da olsa silinir.", s: "Buhârî, Müslim" },
{ t: "'Sübhânallah, elhamdülillah, lâ ilâhe illallah, Allahu ekber' demek, üzerine güneş doğan her şeyden bana daha sevimlidir.", s: "Müslim, Zikir 32" },
{ t: "Kim günde yüz defa 'Lâ ilâhe illallahu vahdehû lâ şerîke leh, lehü'l-mülkü ve lehü'l-hamdü ve hüve alâ külli şey'in kadîr' derse, on köle azat etmiş gibi olur, yüz sevap yazılır, yüz günah silinir ve o gün akşama kadar şeytandan korunur.", s: "Buhârî, Müslim" },
{ t: "'Lâ havle velâ kuvvete illâ billâh' cennet hazinelerinden bir hazinedir.", s: "Buhârî, Müslim" },
{ t: "Rabbini zikreden ile zikretmeyenin misali, diri ile ölünün misali gibidir.", s: "Buhârî, Deavât 66" },
{ t: "Allah'ı o kadar çok anın ki insanlar size 'deli' desin.", s: "Ahmed b. Hanbel, Müsned" },
{ t: "Kalpler paslanır; cilası Allah'ı zikretmektir.", s: "Beyhakî, Şuabü'l-Îmân" },
{ t: "Sizi, amellerin en hayırlısına, Allah katında en temiz olanına, derecelerinizi en çok yükseltenine, altın gümüş infak etmekten daha hayırlısına haber vereyim mi? Allah'ı zikretmek.", s: "Tirmizî, Deavât 6" },
{ t: "Allah buyurur: Ben kulumun beni zannettiği gibiyim; beni andığında onunlayım. Beni içinden anarsa ben de onu içimden anarım; bir topluluk içinde anarsa ben onu daha hayırlı bir toplulukta anarım.", s: "Buhârî, Müslim" },
{ t: "Bana bir karış yaklaşana bir arşın yaklaşırım; bir arşın yaklaşana bir kulaç yaklaşırım; bana yürüyerek gelene ben koşarak giderim.", s: "Buhârî, Müslim" },
{ t: "Dua ibadetin ta kendisidir.", s: "Ebû Dâvûd, Tirmizî" },
{ t: "Dua ibadetin özüdür.", s: "Tirmizî, Deavât 1" },
{ t: "Allah katında duadan daha değerli bir şey yoktur.", s: "Tirmizî, İbn Mâce" },
{ t: "Kim Allah'tan istemezse Allah ona gazap eder.", s: "Tirmizî, Deavât 2" },
{ t: "Kaza ancak dua ile geri çevrilir; ömrü ancak iyilik uzatır.", s: "Tirmizî, Kader 6" },
{ t: "Dua, inen ve inmeyen belâlara fayda verir. Ey Allah'ın kulları, duaya sarılın.", s: "Tirmizî, Deavât 101" },
{ t: "Kabul edileceğine yakînen inanarak dua edin; Allah gafil ve boş bir kalpten gelen duayı kabul etmez.", s: "Tirmizî, Deavât 65" },
{ t: "Sizden biriniz 'Dua ettim de kabul olmadı' diyerek acele etmedikçe duası kabul edilir.", s: "Buhârî, Müslim" },
{ t: "Kul, günah veya akrabalık bağını kesmeyi istemedikçe, duası şu üç şekilden biriyle kabul edilir: Ya dünyada verilir, ya ahirete saklanır, ya da bir kötülük ondan uzaklaştırılır.", s: "Tirmizî, Deavât 9" },
{ t: "Bolluk zamanında Allah'ı tanı ki darlık zamanında O da seni tanısın.", s: "Tirmizî, Ahmed b. Hanbel" },
{ t: "Rabbiniz hayâ sahibi ve kerîmdir; kulu ellerini kaldırıp dua ettiğinde onları boş çevirmekten hayâ eder.", s: "Ebû Dâvûd, Tirmizî" },
{ t: "Bir Müslümanın kardeşi için gıyabında yaptığı dua kabul edilir; başında bir melek 'Âmin, sana da aynısı' der.", s: "Müslim, Zikir 86" },
{ t: "Üç dua şüphesiz kabul edilir: Mazlumun duası, yolcunun duası, anne babanın çocuğu için duası.", s: "Ebû Dâvûd, Tirmizî" },
{ t: "Duanın en hayırlısı Arefe günü yapılan duadır.", s: "Tirmizî, Deavât 122" },
{ t: "Kulun Rabbine en yakın olduğu an secde hâlidir; orada duayı çok yapın.", s: "Müslim, Salât 215" },
{ t: "Dua eden, önce Allah'a hamd etsin, Peygambere salât getirsin, sonra dilediğini istesin.", s: "Ebû Dâvûd, Tirmizî" },
{ t: "Kim bana bir salavat getirirse, Allah ona on rahmet eder.", s: "Müslim, Salât 70" },
{ t: "Kıyamet günü bana en yakın olanınız, bana en çok salavat getireninizdir.", s: "Tirmizî, Vitr 21" },
{ t: "Cimri, yanında adım anıldığında bana salavat getirmeyendir.", s: "Tirmizî, Deavât 100" },
{ t: "Bana salavat getirdiğinizde her nerede olursanız olun, salavatınız bana ulaşır.", s: "Ebû Dâvûd, Menâsik 96" },
{ t: "Her Âdemoğlu hata eder; hata edenlerin en hayırlısı tövbe edenlerdir.", s: "Tirmizî, İbn Mâce" },
{ t: "Allah, kulunun tövbesine, çölde devesini kaybedip sonra bulan kimseden daha çok sevinir.", s: "Buhârî, Müslim" },
{ t: "Kul, can boğaza gelmedikçe tövbesi kabul edilir.", s: "Tirmizî, Deavât 98" },
{ t: "Güneş batıdan doğmadıkça tövbe kapısı kapanmaz.", s: "Müslim, Zikir 43" },
{ t: "Allah, gece günah işleyenin tövbesini kabul etmek için gündüz elini açar; gündüz günah işleyenin tövbesini kabul etmek için gece elini açar.", s: "Müslim, Tevbe 31" },
{ t: "Günahtan tövbe eden, hiç günah işlememiş gibidir.", s: "İbn Mâce, Zühd 30" },
{ t: "Ben günde yüz defa Allah'a tövbe ve istiğfar ederim.", s: "Müslim, Zikir 42" },
{ t: "Kim istiğfarı çokça yaparsa, Allah ona her sıkıntıdan bir çıkış, her üzüntüden bir kurtuluş verir ve ummadığı yerden rızıklandırır.", s: "Ebû Dâvûd, Vitr 26" },
{ t: "Allah'a yemin olsun ki ben günde yetmiş defadan fazla Allah'a istiğfar eder, tövbe ederim.", s: "Buhârî, Deavât 3" },
{ t: "İstiğfarın efendisi (Seyyidü'l-istiğfâr): Allah'ım, sen benim Rabbimsin, senden başka ilâh yoktur…'dur. Kim buna inanarak akşamleyin söyler de o gece ölürse cennete girer.", s: "Buhârî, Deavât 2" },
{ t: "Kim bir günah işler de sonra abdest alıp iki rekât namaz kılar ve Allah'tan bağışlanma dilerse, Allah onu bağışlar.", s: "Ebû Dâvûd, Tirmizî" },
{ t: "Allah'ım! Beni, hatalarımı kar ve dolu suyuyla yıkar gibi temizle.", s: "Buhârî, Müslim" },
{ t: "Allah'ım! Günahımın hepsini; küçüğünü büyüğünü, ilkini sonunu, açığını gizlisini bağışla.", s: "Müslim, Salât 216" },
{ t: "Allah'ım! Sen affedicisin, affı seversin; beni affet.", s: "Tirmizî, Deavât 84" },
{ t: "Allah'ım! Bize dünyada iyilik, ahirette iyilik ver ve bizi cehennem azabından koru.", s: "Buhârî, Müslim" },
{ t: "Allah'ım! Bana hidayet, takvâ, iffet ve gönül zenginliği ver.", s: "Müslim, Zikir 72" },
{ t: "Allah'ım! Üzüntüden, kederden, acizlikten, tembellikten, korkaklıktan, cimrilikten, borç yükünden ve insanların baskısından sana sığınırım.", s: "Buhârî, Deavât 36" },
{ t: "Allah'ım! Sıhhat, afiyet ve güzel ahlâk ver.", s: "Riyâzü's-Sâlihîn" },
{ t: "Sabah akşam 'Allah'ım, bedenime afiyet ver, kulağıma afiyet ver, gözüme afiyet ver' deyin.", s: "Ebû Dâvûd, Edeb 101" },
{ t: "Allah'ım! Beni bana verdiğin nimetlerin yok olmasından, verdiğin afiyetin değişmesinden ve ansızın gelecek azabından sana sığınırım.", s: "Müslim, Zikir 96" },
{ t: "Allah'ım! Kalbimi dinin üzere sabit kıl.", s: "Tirmizî, Kader 7" },
{ t: "Kalpleri evirip çeviren Allah'ım! Kalbimi dinin üzere sabit kıl.", s: "Tirmizî, Deavât 124" },
{ t: "Allah'ım! Bana kendi sevgini, seni sevenin sevgisini ve senin sevgine ulaştıracak ameli sevmeyi nasip et.", s: "Tirmizî, Deavât 73" },
{ t: "Allah'ım! Beni sana şükreden, seni zikreden, senden korkan, sana itaat eden ve sana yönelen bir kul eyle.", s: "Ebû Dâvûd, Tirmizî" },
{ t: "Allah'ım! Fakirlikten, azlıktan ve zilletten sana sığınırım.", s: "Ebû Dâvûd, Nesâî" },
{ t: "Allah'ım! Beni, hakkı hak olarak gösterip ona uymayı, bâtılı bâtıl olarak gösterip ondan kaçınmayı nasip et.", s: "Riyâzü's-Sâlihîn" },
{ t: "Allah'ım! Faydalı ilim, temiz rızık ve makbul amel ver.", s: "İbn Mâce, İkâme 32" },
{ t: "Ya Rabbi! Bana yardım et, aleyhime yardım etme; beni destekle, aleyhime destekleme; bana hile yap, aleyhime hile yapma; bana hidayet ver ve hidayeti kolaylaştır.", s: "Ebû Dâvûd, Tirmizî" },
{ t: "Sabah kalktığında 'Allah'ım, senin sayende sabahladık, senin sayende akşamladık; senin sayende yaşar, senin sayende ölürüz; dönüş sanadır' de.", s: "Tirmizî, Deavât 13" },
{ t: "Yatmadan önce 'Allah'ım senin adınla ölür, senin adınla dirilirim' de; uyanınca 'Bizi öldürdükten sonra dirilten Allah'a hamdolsun, dönüş O'nadır' de.", s: "Buhârî, Deavât 7" },
{ t: "Ev halkıyla yemeğe oturduğunda 'Bismillah' de; yemek bittiğinde 'Elhamdülillah' de.", s: "Riyâzü's-Sâlihîn" },
{ t: "Sabah akşam yedi defa 'Hasbiyallahu lâ ilâhe illâ hüve, aleyhi tevekkeltü ve hüve rabbü'l-arşi'l-azîm' diyene Allah, dünya ve ahiret kaygılarına karşı yeter.", s: "Ebû Dâvûd, Edeb 100" },
{ t: "Kim sabah akşam 'Bismillâhillezî lâ yedurru mea'smihî şey'ün fi'l-ardı ve lâ fi's-semâi ve hüve's-semîu'l-alîm' derse ona hiçbir şey zarar vermez.", s: "Ebû Dâvûd, Tirmizî" },
{ t: "Evden çıkarken 'Bismillah, tevekkeltü alallah, lâ havle velâ kuvvete illâ billâh' diyene 'hidayete erdirildin, korundun, kifayet edildin' denir; şeytan ondan uzaklaşır.", s: "Ebû Dâvûd, Tirmizî" },
{ t: "Bir yere girdiğinde 'Allah'ım, girişimin ve çıkışımın hayırlı olmasını dilerim' de.", s: "Ebû Dâvûd, Edeb 102" },
{ t: "Bir belâya uğrayan kimse görürsen 'Seni bu belâya uğratmayıp diğer yarattıklarından üstün kılan Allah'a hamdolsun' de; o belâ sana ulaşmaz.", s: "Tirmizî, Deavât 38" },
{ t: "Bir musibet geldiğinde 'İnnâ lillâhi ve innâ ileyhi râciûn; Allah'ım, musibetimde bana ecir ver ve daha hayırlısını nasip et' diyene Allah daha hayırlısını verir.", s: "Müslim, Cenâiz 3" },
{ t: "Kim sabahleyin üç defa 'Eûzü billâhi's-semîi'l-alîm mine'ş-şeytâni'r-racîm' der ve Haşr sûresinin son üç âyetini okursa, Allah ona akşama kadar istiğfar edecek yetmiş bin melek görevlendirir.", s: "Tirmizî, Fedâilü'l-Kur'ân 22" },
{ t: "Sizden biriniz dua ettiğinde 'Allah'ım dilersen bana ver' demesin; kesin ve kararlı istesin, isteği büyütsün; Allah'a hiçbir şey büyük gelmez.", s: "Buhârî, Müslim" },
{ t: "Kişinin kendisi, malı ve çocuğu aleyhine beddua etmeyin; Allah'ın duaya icabet ettiği bir saate denk gelir de kabul olunur.", s: "Müslim, Zühd 74" },
{ t: "Allah'ım! Bana ölümün şiddetini kolaylaştır ve son nefeste kelime-i şehadeti nasip et.", s: "Riyâzü's-Sâlihîn" },
{ t: "Allah'ım! Bizi Kur'an'ın şefaatine nail eyle; onu bize hüccet kıl, aleyhimize kılma.", s: "Riyâzü's-Sâlihîn" },
{ t: "Kur'an'ı üç günden az sürede hatmeden onu anlamamıştır.", s: "Ebû Dâvûd, Tirmizî" },
{ t: "Her ay Kur'an'ı hatmet.", s: "Buhârî, Müslim" },
{ t: "Kim Kur'an'ı okur ve onunla amel ederse, kıyamet günü anne babasına ışığı güneşten daha parlak bir taç giydirilir.", s: "Ebû Dâvûd, Ahmed b. Hanbel" },
{ t: "Kur'an okumak ve dinlemek kalbe huzur, göze nur verir.", s: "Riyâzü's-Sâlihîn" },
{ t: "Sizin en hayırlınız, Kur'an'ı ezberleyip başkalarına öğretendir; Kur'an'ı yaşayan mümin şereflidir.", s: "Riyâzü's-Sâlihîn" },
{ t: "Kur'an'ı öğrenin ve onu okuyun; onu öğrenip okuyan ve gece ibadetinde okuyan kimse, misk dolu bir kabın kokusunu yayan kimse gibidir.", s: "Tirmizî, Nesâî" },
{ t: "Kur'an ehli, Allah'ın ehli ve seçkin kullarıdır.", s: "Nesâî, İbn Mâce" },

/* ── TOPLUM: KARDEŞLİK, SELÂM, ZİYARET, HASTA, CENAZE, TİCARET, HELÂL KAZANÇ, ADALET, YÖNETİM, EMANET ── */
{ t: "Müslüman Müslümanın kardeşidir; ona zulmetmez, onu düşmana teslim etmez, onu küçük görmez.", s: "Buhârî, Müslim" },
{ t: "Müslümanın Müslüman üzerindeki hakkı beştir: Selâm almak, hastayı ziyaret etmek, cenazeye katılmak, davete icabet etmek, aksırana 'yerhamükellah' demek.", s: "Buhârî, Müslim" },
{ t: "Müslümanın Müslüman üzerinde altı hakkı vardır: Karşılaşınca selâm ver, davet ederse git, nasihat isterse nasihat et, aksırıp hamd ederse ona dua et, hastalanınca ziyaret et, ölünce cenazesine katıl.", s: "Müslim, Selâm 5" },
{ t: "İman etmedikçe cennete giremezsiniz; birbirinizi sevmedikçe iman etmiş olmazsınız. Size bir şey söyleyeyim mi ki onu yaparsanız birbirinizi seversiniz: Aranızda selâmı yayın.", s: "Müslim, Îmân 93" },
{ t: "Binitli yayaya, yürüyen oturana, az çok topluluğa selâm verir.", s: "Buhârî, Müslim" },
{ t: "Küçük büyüğe, geçen oturana, az çoğa selâm verir.", s: "Buhârî, İstizân 5" },
{ t: "İnsanların Allah'a en yakını, onlara ilk selâm verendir.", s: "Ebû Dâvûd, Edeb 133" },
{ t: "Tanıdığına ve tanımadığına selâm ver.", s: "Buhârî, Müslim" },
{ t: "Selâm vermeden önce söze başlamayın.", s: "Tirmizî, İstizân 11" },
{ t: "Sizden biriniz kardeşiyle karşılaşınca selâm versin; arada ağaç, duvar ya da taş girer de tekrar karşılaşırsa yine selâm versin.", s: "Ebû Dâvûd, Edeb 135" },
{ t: "İki Müslüman karşılaşıp tokalaşırsa, ayrılmadan önce günahları bağışlanır.", s: "Ebû Dâvûd, Tirmizî" },
{ t: "Kim bir hastayı ziyaret ederse, dönünceye kadar cennetin bahçelerindedir.", s: "Müslim, Birr 39" },
{ t: "Bir Müslüman, hasta kardeşini sabah ziyaret ederse akşama kadar yetmiş bin melek ona dua eder; akşam ziyaret ederse sabaha kadar dua eder ve cennette ona bir bahçe olur.", s: "Tirmizî, Cenâiz 2" },
{ t: "Allah kıyamet günü buyurur: Ey Âdemoğlu, hastalandım beni ziyaret etmedin. Kul: 'Sen âlemlerin Rabbisin, seni nasıl ziyaret edeyim?' der. Allah: 'Falan kulum hastalandı, ziyaret etmedin; etseydin beni onun yanında bulurdun' buyurur.", s: "Müslim, Birr 43" },
{ t: "Hastayı ziyaret edince ona 'Geçmiş olsun, bu hastalık temizliktir inşallah' de.", s: "Buhârî, Merdâ 10" },
{ t: "Hastanın yanına girince ona dua isteyin; hastanın duası meleklerin duası gibidir.", s: "İbn Mâce, Cenâiz 1" },
{ t: "Hastalarınızı sadaka ile tedavi edin.", s: "Beyhakî" },
{ t: "Bir hastayı ziyaret edip yedi defa 'Es'elullahe'l-azîm rabbe'l-arşi'l-azîm en yeşfiyek' diyen kimsenin, hastanın eceli gelmemişse, Allah onu iyileştirir.", s: "Ebû Dâvûd, Tirmizî" },
{ t: "Her derdin bir devası vardır; derdin devası bulunursa Allah'ın izniyle iyileşir.", s: "Müslim, Selâm 69" },
{ t: "Allah hiçbir hastalık indirmemiştir ki şifasını da indirmiş olmasın.", s: "Buhârî, Tıb 1" },
{ t: "Tedavi olun ey Allah'ın kulları! Allah, ihtiyarlık dışında, şifasını yaratmadığı hiçbir hastalık indirmemiştir.", s: "Ebû Dâvûd, Tirmizî" },
{ t: "Kara çörek otu (habbetü's-sevdâ) ölüm dışında her derde devadır.", s: "Buhârî, Müslim" },
{ t: "Bal şifadır; Kur'an şifadır. Size iki şifayı tavsiye ederim: Bal ve Kur'an.", s: "İbn Mâce, Tıb 7" },
{ t: "Cenazeye katılıp namazını kılana bir kırat, defnedilinceye kadar bekleyene iki kırat sevap vardır; bir kırat Uhud dağı kadardır.", s: "Buhârî, Müslim" },
{ t: "Cenazeyi hızlı götürün; iyi ise onu hayra ulaştırmış olursunuz, kötü ise omuzlarınızdan atmış olursunuz.", s: "Buhârî, Müslim" },
{ t: "Ölülerinizin iyiliklerini anın, kötülüklerini söylemekten kaçının.", s: "Ebû Dâvûd, Tirmizî" },
{ t: "Ölülere sövmeyin; onlar yaptıklarına kavuşmuşlardır.", s: "Buhârî, Cenâiz 97" },
{ t: "Kabirleri ziyaret edin; kabirler ahireti hatırlatır.", s: "Müslim, Cenâiz 108" },
{ t: "Kabirlere gittiğinizde şöyle deyin: Selâm size ey müminler diyarının ahalisi! İnşallah biz de size kavuşacağız. Allah'tan bize ve size afiyet dilerim.", s: "Müslim, Cenâiz 104" },
{ t: "Ölünün kabre konulmasından sonra kabri başında durup onun için dua edin; şu an sorguya çekiliyor.", s: "Ebû Dâvûd, Cenâiz 73" },
{ t: "Kabir ya cennet bahçelerinden bir bahçe ya da cehennem çukurlarından bir çukurdur.", s: "Tirmizî, Sıfatü'l-Kıyâme 26" },
{ t: "Ölüm bir müjdedir: Mümin için Allah'a kavuşma, kâfir için azaptan haber.", s: "Riyâzü's-Sâlihîn" },
{ t: "Bir kimse ölünce 'İnnâ lillâhi ve innâ ileyhi râciûn' deyin ve sabredin; sabır ilk andadır.", s: "Riyâzü's-Sâlihîn" },
{ t: "Kişi bir cenazenin ardından ağlayabilir ama bağırıp çağırmasın, yüzünü yırtmasın.", s: "Buhârî, Müslim" },
{ t: "Gözler yaşarır, kalp hüzünlenir; ama biz Rabbimizin razı olmayacağı bir söz söylemeyiz.", s: "Buhârî, Müslim" },
{ t: "Bir çocuğu ölen anne baba sabrederse, o çocuk ona cennette şefaatçi olur.", s: "Buhârî, Müslim" },
{ t: "Ölülerinize Yasin okuyun.", s: "Ebû Dâvûd, İbn Mâce" },
{ t: "Cenazeye katılın; o size ahireti hatırlatır.", s: "Riyâzü's-Sâlihîn" },
{ t: "Doğru sözlü, güvenilir tüccar; peygamberler, sıddîklar ve şehitlerle beraberdir.", s: "Tirmizî, Büyû' 4" },
{ t: "Alan ve satan, ayrılmadıkça muhayyerdirler. Doğru söyler ve açık davranırlarsa alışverişleri bereketli olur; gizler ve yalan söylerlerse bereketi kaldırılır.", s: "Buhârî, Müslim" },
{ t: "Bizi aldatan bizden değildir.", s: "Müslim, Îmân 164" },
{ t: "Alışverişte ölçü ve tartıyı tam yapın; eksik verenler helâk olmuştur.", s: "Riyâzü's-Sâlihîn" },
{ t: "Kim bir malı satarken kusurunu gizlerse, Allah'ın gazabına uğrar; melekler ona lânet eder.", s: "İbn Mâce, Ticârât 45" },
{ t: "Faizden sakının; Allah faizin bereketini yok eder, sadakayı artırır.", s: "Riyâzü's-Sâlihîn" },
{ t: "Faiz yiyene, yedirene, kâtibine ve şahitlerine lânet olsun; onlar günahta eşittir.", s: "Müslim, Müsâkât 106" },
{ t: "Faizin yetmiş üç çeşidi vardır; en hafifi kişinin annesiyle zina etmesi gibidir.", s: "Hâkim, el-Müstedrek" },
{ t: "Helâl kazanç aramak, farzdan sonra bir farzdır.", s: "Beyhakî, Şuabü'l-Îmân" },
{ t: "Haramdan beslenen hiçbir beden cennete giremez; ateş ona daha lâyıktır.", s: "Ahmed b. Hanbel, Müsned" },
{ t: "Bir adam uzun yolculuktan tozlu, dağınık hâlde ellerini göğe kaldırıp 'Ya Rabbi, ya Rabbi' der; ama yediği haram, içtiği haram, giydiği haram, haramla beslenmiş; onun duası nasıl kabul olsun?", s: "Müslim, Zekât 65" },
{ t: "Kişinin ağzına giren lokmanın helâl olması, kabul olan duanın şartıdır.", s: "Riyâzü's-Sâlihîn" },
{ t: "İşçiye ücretini alnının teri kurumadan verin.", s: "İbn Mâce, Rühûn 4" },
{ t: "Üç kişinin kıyamet günü hasmı benim: Benim adımla söz verip cayan, hür bir insanı satıp parasını yiyen, bir işçiyi çalıştırıp ücretini vermeyen.", s: "Buhârî, Büyû' 106" },
{ t: "Sizden biri ip alıp dağdan odun toplayıp sırtında getirip satması, insanlardan istemesinden hayırlıdır.", s: "Buhârî, Zekât 50" },
{ t: "Şüphesiz Allah, kulunu bir işi güzel yaptığında sever.", s: "Beyhakî" },
{ t: "Sabahın erken saatleri ümmetim için bereketli kılınmıştır.", s: "Ebû Dâvûd, Tirmizî" },
{ t: "Allah'ım, ümmetimin erken kalkmasını bereketli kıl.", s: "Tirmizî, Büyû' 6" },
{ t: "Bir hizmetçi, efendisine dünyada iyi hizmet eder ve Rabbine de güzel ibadet ederse, ona iki sevap vardır.", s: "Buhârî, Müslim" },
{ t: "Adaletli olan yöneticiler kıyamet günü Rahmân'ın sağında nurdan minberler üzerindedir.", s: "Müslim, İmâre 18" },
{ t: "Allah'ın gölgesinden başka gölge olmayan günde yedi sınıf O'nun gölgesindedir: Adil yönetici, Allah'a ibadetle yetişen genç, kalbi mescide bağlı kimse, Allah için birbirini seven iki kişi, güzel bir kadın davet ettiğinde 'Allah'tan korkarım' diyen kimse, sağ elinin verdiğini sol eli bilmeyen kimse, yalnızken Allah'ı anıp gözyaşı döken kimse.", s: "Buhârî, Müslim" },
{ t: "Bir yönetici, yönettiği halka hile yaparak ölürse, Allah ona cenneti haram kılar.", s: "Buhârî, Müslim" },
{ t: "Kim bir topluluğun idaresini üstlenir de onların işini gücü yettiğince gözetmezse, cennetin kokusunu alamaz.", s: "Riyâzü's-Sâlihîn" },
{ t: "Ey Allah'ım! Ümmetimin işini üstlenip onlara zorluk çıkarana sen de zorluk çıkar; kolaylık gösterene sen de kolaylık göster.", s: "Müslim, İmâre 19" },
{ t: "Yöneticilik emanettir; onu hakkıyla yerine getirmeyen için kıyamet günü pişmanlık ve rezilliktir.", s: "Müslim, İmâre 16" },
{ t: "Yöneticiye Allah'a isyanı emretmedikçe itaat gerekir; isyan emrederse itaat yoktur.", s: "Buhârî, Müslim" },
{ t: "Zalim bir yöneticiye karşı hakkı söylemek en faziletli cihattır.", s: "Ebû Dâvûd, Tirmizî" },
{ t: "Hâkim üç kısımdır: İkisi cehennemde, biri cennettedir. Hakkı bilip hükmeden cennette; hakkı bilip hükmetmeyen ve bilmeden hükmeden cehennemdedir.", s: "Ebû Dâvûd, Tirmizî" },
{ t: "Hâkim öfkeliyken hüküm vermesin.", s: "Buhârî, Müslim" },
{ t: "Sizden önceki toplumlar şu yüzden helâk oldu: İçlerinden şerefli biri çalınca bırakırlar, zayıf biri çalınca cezalandırırlardı. Allah'a yemin ederim, Muhammed'in kızı Fâtıma da çalsaydı elini keserdim.", s: "Buhârî, Müslim" },
{ t: "Emaneti yerine getirin; size ihanet edene siz ihanet etmeyin.", s: "Ebû Dâvûd, Tirmizî" },
{ t: "Emanet kaldırılınca kıyameti bekleyin. 'Nasıl kaldırılır?' 'İş ehli olmayana verilince.'", s: "Buhârî, İlim 2" },
{ t: "Hak sahibine hakkı verilmeden helâlleşmek olmaz.", s: "Riyâzü's-Sâlihîn" },
{ t: "Bir Müslümanın malını yalan yeminle alan kimse Allah'ın gazabıyla karşılaşır.", s: "Buhârî, Müslim" },
{ t: "Kim bir karış toprağı haksız yere alırsa, kıyamet günü yedi kat yer boynuna dolanır.", s: "Buhârî, Müslim" },
{ t: "İnsanların içinden hayırsız olanları, alışverişte yeminini çok edenlerdir.", s: "Riyâzü's-Sâlihîn" },
{ t: "Yemin malı sürdürür ama bereketi giderir.", s: "Buhârî, Müslim" },
{ t: "Borç, gecenin kederi, gündüzün zilletidir.", s: "Beyhakî" },
{ t: "Şehidin bütün günahları bağışlanır; borç hariç.", s: "Müslim, İmâre 119" },
{ t: "Kim insanların malını ödemek niyetiyle alırsa Allah onun borcunu ödetir; telef etmek niyetiyle alırsa Allah onu telef eder.", s: "Buhârî, İstikrâz 2" },
{ t: "Ödemeye gücü yeten kimsenin borcunu geciktirmesi, onun şerefini lekelemeyi ve cezalandırılmasını helâl kılar.", s: "Ebû Dâvûd, Nesâî" },
{ t: "Davete icabet edin; davete gitmeyen Allah ve Resûlüne isyan etmiştir.", s: "Buhârî, Müslim" },
{ t: "Yemeğin en kötüsü, sadece zenginlerin çağrılıp fakirlerin bırakıldığı düğün yemeğidir.", s: "Buhârî, Müslim" },
{ t: "Bir davete çağrıldığında git; oruçluysan dua et, değilsen ye.", s: "Müslim, Nikâh 106" },
{ t: "Bir kişi bir iyilik yapınca 'Allah sana hayır versin' deyin.", s: "Riyâzü's-Sâlihîn" },
{ t: "Bir topluluğa geldiğinde selâm ver; oturmak istersen otur; kalkarken selâm ver; ilk selâm sonuncusundan üstün değildir.", s: "Ebû Dâvûd, Tirmizî" },
{ t: "Sizden biri, başkasını yerinden kaldırıp yerine oturmasın; fakat sıkışıp yer açın.", s: "Buhârî, Müslim" },
{ t: "Yolun hakkını verin: Gözü haramdan sakınmak, eziyeti kaldırmak, selâmı almak, iyiliği emredip kötülükten sakındırmak.", s: "Buhârî, Müslim" },
{ t: "Kim bir kötülük görürse eliyle düzeltsin; gücü yetmezse diliyle; ona da gücü yetmezse kalbiyle buğzetsin; bu imanın en zayıfıdır.", s: "Müslim, Îmân 78" },
{ t: "İyiliği emredin, kötülükten sakındırın; yoksa Allah size bir azap gönderir de dua edersiniz, kabul olmaz.", s: "Tirmizî, Fiten 9" },
{ t: "Ümmetimin helâk olmaması için, insanlar zalimi görüp de elini tutmadıkça, Allah hepsine azap verir.", s: "Ebû Dâvûd, Tirmizî" },
{ t: "Bir gemide olanlar gibi: Alt kattakiler 'Su almak için delik açalım' derlerse, üsttekiler engel olmazsa hep birlikte batarlar.", s: "Buhârî, Şirket 6" },
{ t: "Kim bir Müslümanı örterse Allah onu dünya ve ahirette örter.", s: "Müslim, Zikir 38" },
{ t: "Bir kimse Müslüman kardeşinin bir hakkını başkasına söylerse, o hakkı kendisine yazılan bir hak gibi olur.", s: "Riyâzü's-Sâlihîn" },
{ t: "Cömertlik cennette bir ağaçtır; dalları dünyaya sarkar. Kim bir dalına tutunursa onu cennete çeker.", s: "Beyhakî" },
{ t: "İnsanlara yardım etmek sadakadır; iki kişi arasında adaletle hükmetmek sadakadır; bir kimseye bineğine binmesinde yardım etmek sadakadır; güzel söz sadakadır; namaza attığın her adım sadakadır; yoldan eziyeti kaldırmak sadakadır.", s: "Buhârî, Müslim" },
{ t: "Bir kimsenin bir başka kimseye, 'Gel, Allah'ın rızası için şunu yapalım' demesi de sadakadır.", s: "Riyâzü's-Sâlihîn" },
{ t: "İki kişinin arasını düzeltmek en faziletli sadakadır.", s: "Ebû Dâvûd, Tirmizî" },
{ t: "İnsanların arasını düzeltmek için iyi söz taşıyan yalancı sayılmaz.", s: "Buhârî, Müslim" },
{ t: "Nasihat etmek istediğin kimseye gizlice söyle; açıkça söylersen onu utandırırsın.", s: "Riyâzü's-Sâlihîn" },
{ t: "Kişi kardeşinin aynasıdır; onda bir kusur görürse düzeltir.", s: "Ebû Dâvûd, Tirmizî" },
{ t: "Allah katında en sevimli amellerden biri, Müslümanın kalbine sevinç sokmandır.", s: "Taberânî" },
{ t: "İnsanlar arasında Allah'a en sevgili olanlar, insanlara en faydalı olanlardır.", s: "Taberânî" },
{ t: "Kişinin gücü yetiyorsa yardım etsin; yoksa bir hayırla yol göstersin; o da olmazsa şerrini insanlardan uzak tutsun; bu da sadakadır.", s: "Buhârî, Müslim" },
{ t: "Bir Müslümanı sevindiren, bir müminin ihtiyacını gideren, borcunu ödeyen kimse Allah'ın rızasını kazanır.", s: "Taberânî" },
{ t: "Halka hizmet eden, onların efendisidir.", s: "Deylemî" },
{ t: "Yolculukta arkadaşlarına hizmet eden, onlardan üstündür.", s: "Riyâzü's-Sâlihîn" },
{ t: "Kişi, bir topluluğun hizmetçisi olursa kıyamet günü onların efendisidir.", s: "Riyâzü's-Sâlihîn" },
{ t: "Bir Müslümanın işini gören kimse, Allah yolunda savaşan gibidir.", s: "Riyâzü's-Sâlihîn" },
{ t: "Yetimi koruyan ve dul kadına yardım eden, gece namaz kılıp gündüz oruç tutan gibidir.", s: "Buhârî, Müslim" },
{ t: "Bir kimse din kardeşinin ihtiyacını giderirse, Allah da onun ihtiyacını giderir.", s: "Riyâzü's-Sâlihîn" },
{ t: "Bir adamın ihtiyacını gidermen için yürümen, mescidimde bir ay itikâf etmenden daha hayırlıdır.", s: "Taberânî" },
{ t: "İnsanlar arasında adaletle hükmet; zalimden mazlumun hakkını al.", s: "Riyâzü's-Sâlihîn" },
{ t: "Adalet, dünyanın direği; zulüm, harabesidir.", s: "Riyâzü's-Sâlihîn" },

/* ── DÜNYA-AHİRET, ÖLÜM, KIYAMET, CENNET-CEHENNEM, ZÜHD, TEVEKKÜL ── */
{ t: "Dünyanın Allah katında sivrisinek kanadı kadar değeri olsaydı, kâfire bir yudum su içirmezdi.", s: "Tirmizî, Zühd 13" },
{ t: "Dünya mel'undur; içindekiler de mel'undur. Ancak Allah'ı zikretmek, O'na yaklaştıran şeyler, âlim ve öğrenci hariç.", s: "Tirmizî, Zühd 14" },
{ t: "Benim dünya ile ne işim var? Ben dünyada bir ağacın altında gölgelenip sonra bırakıp giden yolcu gibiyim.", s: "Tirmizî, Zühd 44" },
{ t: "Dünyada zâhid ol ki Allah seni sevsin; insanların elindekine göz dikme ki insanlar seni sevsin.", s: "İbn Mâce, Zühd 1" },
{ t: "Dünya sevgisi bütün hataların başıdır.", s: "Beyhakî, Şuabü'l-Îmân" },
{ t: "Ahirete göre dünya, birinizin parmağını denize daldırıp çıkardığında parmağına bulaşan su kadardır.", s: "Müslim, Cennet 55" },
{ t: "Ölüm için hazırlan; ölüm sana bir habercinin gelmesini beklemez.", s: "Riyâzü's-Sâlihîn" },
{ t: "Her nefis ölümü tadacaktır; kabir onun için ilk menzildir.", s: "Riyâzü's-Sâlihîn" },
{ t: "Ölüyü üç şey takip eder: Ailesi, malı ve ameli. İkisi döner, biri kalır: Ailesi ve malı döner, ameli kalır.", s: "Buhârî, Müslim" },
{ t: "Kişi öldüğünde kıyameti kopmuştur.", s: "Riyâzü's-Sâlihîn" },
{ t: "İnsanların en ferasetlisi ölümü en çok hatırlayandır.", s: "İbn Mâce, Zühd 31" },
{ t: "Ölüm bir köprüdür; dostu dosta ulaştırır.", s: "Riyâzü's-Sâlihîn" },
{ t: "Gelecek belâlar için kaygılanmayın; Rabbinize güvenin.", s: "Riyâzü's-Sâlihîn" },
{ t: "Allah'a hakkıyla tevekkül etseydiniz, kuşları rızıklandırdığı gibi sizi de rızıklandırırdı; sabah aç çıkar, akşam tok dönerler.", s: "Tirmizî, Zühd 33" },
{ t: "Deveni bağla, sonra tevekkül et.", s: "Tirmizî, Sıfatü'l-Kıyâme 60" },
{ t: "Sana fayda verecek şeye sarıl, Allah'tan yardım iste, acizlik gösterme. Başına bir şey gelirse 'Keşke şöyle yapsaydım' deme; 'Allah'ın takdiri, dilediğini yaptı' de. Çünkü 'keşke' şeytanın işine kapı açar.", s: "Müslim, Kader 34" },
{ t: "Kuvvetli mümin, zayıf müminden hayırlı ve Allah'a daha sevimlidir; her ikisinde de hayır vardır.", s: "Müslim, Kader 34" },
{ t: "Bil ki, ümmet toplanıp sana bir fayda vermek istese, Allah'ın yazdığından fazlasını veremez; zarar vermek istese, Allah'ın yazdığından fazlasını veremez. Kalemler kaldırılmış, sayfalar kurumuştur.", s: "Tirmizî, Sıfatü'l-Kıyâme 59" },
{ t: "Allah'ı gözet ki O da seni gözetsin; Allah'ı gözet ki O'nu karşında bulasın. İstediğinde Allah'tan iste, yardım dilediğinde Allah'tan dile.", s: "Tirmizî, Sıfatü'l-Kıyâme 59" },
{ t: "Kimin tasası ahiret olursa Allah onun kalbine zenginlik koyar, işini toparlar, dünya ona boyun eğerek gelir. Kimin tasası dünya olursa Allah fakirliği gözünün önüne koyar, işini dağıtır; dünyadan da ancak takdir edileni alır.", s: "Tirmizî, Sıfatü'l-Kıyâme 30" },
{ t: "Nefsini hesaba çeken, ahiret için amel eden akıllıdır.", s: "Tirmizî, Sıfatü'l-Kıyâme 25" },
{ t: "Kıyamet günü insanlar kabirlerinden yalınayak, çıplak ve sünnetsiz olarak diriltilir.", s: "Buhârî, Müslim" },
{ t: "Kıyametin alâmetlerinden: İlim kalkar, cehalet yayılır, zina çoğalır, içki çoğalır, kadınlar çoğalır erkekler azalır.", s: "Buhârî, Müslim" },
{ t: "Kıyamet, yalnız kötü insanlar üzerine kopar.", s: "Müslim, Fiten 131" },
{ t: "Sizden birinizin elinde bir fidan varken kıyamet koparsa, dikebiliyorsa diksin.", s: "Ahmed b. Hanbel, Müsned" },
{ t: "Kıyamet günü kişi, ömrünü nerede geçirdiğinden sorulmadan adım atamaz.", s: "Tirmizî, Sıfatü'l-Kıyâme 1" },
{ t: "Kıyamet günü havuzumun başında sizi beklerim; ondan içen bir daha susamaz.", s: "Buhârî, Müslim" },
{ t: "Benim şefaatim, ümmetimden büyük günah işleyenler içindir.", s: "Ebû Dâvûd, Tirmizî" },
{ t: "Her peygamberin kabul olunan bir duası vardır; ben duamı kıyamet günü ümmetime şefaat için sakladım.", s: "Buhârî, Müslim" },
{ t: "Cennette hiçbir gözün görmediği, hiçbir kulağın işitmediği, hiçbir beşerin aklına gelmeyen nimetler vardır.", s: "Buhârî, Müslim" },
{ t: "Cennette bir ağaç vardır ki bir binici gölgesinde yüz yıl gider de bitiremez.", s: "Buhârî, Müslim" },
{ t: "Cennetin en aşağı derecesindeki kimseye dünyanın on misli verilir.", s: "Müslim, Îmân 302" },
{ t: "Cennete giren nimet içindedir, sıkıntı görmez; elbisesi eskimez, gençliği tükenmez.", s: "Müslim, Cennet 21" },
{ t: "Cennet ehline 'Sağlıklısınız, hiç hastalanmayacaksınız; yaşayacaksınız, hiç ölmeyeceksiniz; genç kalacaksınız, hiç yaşlanmayacaksınız' diye seslenilir.", s: "Müslim, Cennet 22" },
{ t: "Cennette bir kamçı kadar yer, dünya ve içindekilerden hayırlıdır.", s: "Buhârî, Bed'ü'l-Halk 8" },
{ t: "Cehennem ateşi, dünya ateşinin yetmiş katıdır.", s: "Buhârî, Müslim" },
{ t: "Cehennemde en hafif azap görecek kimse, ayağının altına konulan korla beyni kaynayandır.", s: "Buhârî, Müslim" },
{ t: "Kim Allah'tan cenneti üç defa isterse cennet 'Allah'ım onu cennete koy' der; kim cehennemden üç defa sığınırsa cehennem 'Allah'ım onu cehennemden koru' der.", s: "Tirmizî, Nesâî" },
{ t: "Hakkı olmayan birine 'efendim' demeyin; o kişi kötü ise Rabbinizi öfkelendirmiş olursunuz.", s: "Ebû Dâvûd, Edeb 83" },
{ t: "İnsanların en çok belâya uğrayanları peygamberler, sonra derece derece diğer salihlerdir. Kişi dinine göre imtihan olunur.", s: "Tirmizî, İbn Mâce" },
{ t: "Mümin erkeğin ve mümin kadının canı, malı, evladı için belâ eksik olmaz; sonunda Allah'a günahsız kavuşur.", s: "Tirmizî, Zühd 57" },
{ t: "Sizin benim gördüğümü görmüş olsaydınız az güler çok ağlardınız.", s: "Buhârî, Müslim" },
{ t: "Bir kul Allah'ın rahmetinin genişliğini bilse cennete girmek için yeterli göremez; azabının şiddetini bilse cehennemden kurtulmayı ummazdı.", s: "Müslim, Tevbe 23" },
{ t: "Allah'ın yüz rahmeti vardır; birini yeryüzüne indirmiştir; onunla anneler yavrularına merhamet eder; doksan dokuzunu kıyamet günü kulları için saklamıştır.", s: "Buhârî, Müslim" },
{ t: "Allah'ın rahmeti gazabını geçmiştir.", s: "Buhârî, Müslim" },
{ t: "Kul, korku ile ümit arasında olsun.", s: "Riyâzü's-Sâlihîn" },
{ t: "Bir kimse ölüm anındayken Allah'a hüsnüzan etsin; O, kulunun zannı üzeredir.", s: "Müslim, Cennet 81" },
{ t: "Ölüm anında Allah'ın rahmetini umun; ümit, kalbin ilacıdır.", s: "Riyâzü's-Sâlihîn" },

/* ── YEME-İÇME, GİYİM, UYKU, YOLCULUK, HAYVANLAR, ÇEVRE, TEMİZLİK ── */
{ t: "Sizden biriniz yemek yerken sağ eliyle yesin, içerken sağ eliyle içsin; şeytan sol eliyle yer ve içer.", s: "Müslim, Eşribe 105" },
{ t: "Ey oğul! Bismillah de, sağ elinle ye ve önünden ye.", s: "Buhârî, Müslim" },
{ t: "Yemekten önce ve sonra el yıkamak bereket getirir.", s: "Ebû Dâvûd, Tirmizî" },
{ t: "Âdemoğlu midesinden daha kötü bir kap doldurmamıştır. Belini doğrultacak birkaç lokma yeter. Mutlaka gerekirse üçte bir yemeğe, üçte bir suya, üçte bir nefese.", s: "Tirmizî, Zühd 47" },
{ t: "Mümin bir bağırsakla, kâfir yedi bağırsakla yer.", s: "Buhârî, Müslim" },
{ t: "İki kişilik yemek üç kişiye, üç kişilik yemek dört kişiye yeter.", s: "Buhârî, Müslim" },
{ t: "Yemeği birlikte yiyin, dağılmayın; bereket topluluktadır.", s: "Ebû Dâvûd, İbn Mâce" },
{ t: "Yemek yerken düşen lokmayı alıp temizleyip yiyin; şeytana bırakmayın.", s: "Müslim, Eşribe 135" },
{ t: "Sizden biriniz yemek yedikten sonra parmaklarını yalasın; bereketin hangisinde olduğunu bilemez.", s: "Müslim, Eşribe 136" },
{ t: "Yemeği üfleyerek soğutmayın.", s: "Tirmizî, Eşribe 15" },
{ t: "Suyu üç nefeste için; ayakta içmeyin.", s: "Müslim, Eşribe 112" },
{ t: "Kap yemeğe uzanmadan önce 'Bismillah' deyin; unutursanız 'Bismillâhi evvelehû ve âhirehû' deyin.", s: "Ebû Dâvûd, Tirmizî" },
{ t: "Allah, kulunun bir lokma yiyip hamd etmesinden, bir yudum içip hamd etmesinden razı olur.", s: "Müslim, Zikir 89" },
{ t: "Yemekten sonra 'Elhamdülillâhillezî et'amenâ ve sekânâ ve cealenâ müslimîn' diyin.", s: "Ebû Dâvûd, Tirmizî" },
{ t: "Yemek yedikten sonra 'Bizi doyuran, içiren ve Müslüman kılan Allah'a hamdolsun' diyenin geçmiş günahları bağışlanır.", s: "Ebû Dâvûd, Tirmizî" },
{ t: "Hiç kimse asla yemeği kötülemedi; hoşuna giderse yerdi, gitmezse bırakırdı.", s: "Buhârî, Müslim" },
{ t: "Sirke ne güzel katıktır.", s: "Müslim, Eşribe 167" },
{ t: "Zeytinyağı yiyin ve sürünün; o mübarek bir ağaçtandır.", s: "Tirmizî, Et'ime 43" },
{ t: "Hurma ile iftar edin; hurma bereketlidir.", s: "Ebû Dâvûd, Tirmizî" },
{ t: "Acve hurmasından sabahleyin yedi tane yiyene o gün zehir ve sihir zarar vermez.", s: "Buhârî, Müslim" },
{ t: "Her sarhoşluk veren haramdır.", s: "Buhârî, Müslim" },
{ t: "Çoğu sarhoş eden şeyin azı da haramdır.", s: "Ebû Dâvûd, Tirmizî" },
{ t: "İçki bütün kötülüklerin anasıdır.", s: "Nesâî, Eşribe 44" },
{ t: "İçkiye, sıkana, sıktırana, içene, içirene, taşıyana, taşıtana, satana, satın alana lânet olsun.", s: "Ebû Dâvûd, Tirmizî" },
{ t: "Altın ve gümüş kaplardan yiyip içmeyin; onlar dünyada kâfirlerin, ahirette sizindir.", s: "Buhârî, Müslim" },
{ t: "Allah temizdir, temizi sever; naziftir, nezafeti sever; kerîmdir, keremi sever; cömerttir, cömertliği sever. Evlerinizin çevresini temizleyin.", s: "Tirmizî, Edeb 41" },
{ t: "Sizden biri yeni bir elbise giydiğinde 'Allah'ım, bunu bana giydiren sana hamdolsun' desin.", s: "Ebû Dâvûd, Tirmizî" },
{ t: "Kim yeni elbise giyer de 'Beni giydiren, kuvvet ve gücüm olmadan bana rızık veren Allah'a hamdolsun' derse geçmiş günahları bağışlanır.", s: "Ebû Dâvûd, Tirmizî" },
{ t: "Beyaz giyin; o elbiselerin en hayırlısıdır; ölülerinizi de onunla kefenleyin.", s: "Ebû Dâvûd, Tirmizî" },
{ t: "Erkeklere altın ve ipek haram, kadınlara helâldir.", s: "Ebû Dâvûd, Tirmizî" },
{ t: "Kim şöhret elbisesi giyerse, Allah kıyamet günü ona zillet elbisesi giydirir.", s: "Ebû Dâvûd, İbn Mâce" },
{ t: "Yatağa girdiğinde sağ tarafına yat ve 'Allah'ım, kendimi sana teslim ettim' de.", s: "Buhârî, Müslim" },
{ t: "Uyumadan önce lambaları söndürün, kapıları kapatın, kapları örtün, su tulumlarının ağzını bağlayın.", s: "Buhârî, Müslim" },
{ t: "Yüzüstü yatmak Allah'ın sevmediği bir yatıştır.", s: "Ebû Dâvûd, Tirmizî" },
{ t: "Biriniz uykudan uyanınca üç defa burnuna su çekip sümkürsün; şeytan burnunda geceler.", s: "Buhârî, Müslim" },
{ t: "Rüya üç türlüdür: Allah'tan müjde, şeytandan korkutma, kişinin kendi düşüncelerinden olan.", s: "Buhârî, Müslim" },
{ t: "Güzel rüya Allah'tandır; kötü rüya şeytandandır. Kötü rüya gören sol tarafına üç defa üflesin ve şerrinden Allah'a sığınsın; o zaman zarar vermez.", s: "Buhârî, Müslim" },
{ t: "Sizden biri hoşuna giden bir rüya görürse onu yalnız sevdiğine anlatsın.", s: "Buhârî, Müslim" },
{ t: "Güzel rüya, peygamberliğin kırk altı cüzünden bir cüzdür.", s: "Buhârî, Müslim" },
{ t: "Yolculuk azaptan bir parçadır; işini bitirince hemen ailesine dönsün.", s: "Buhârî, Müslim" },
{ t: "Bir kimse yalnız yolculuk etmesin; üç kişi yolculuk ederse birini emir seçsinler.", s: "Ebû Dâvûd, Cihâd 80" },
{ t: "Bineğe bindiğinde 'Bunu bizim hizmetimize veren Allah'ı tesbih ederim; biz buna güç yetiremezdik' de.", s: "Ebû Dâvûd, Tirmizî" },
{ t: "Yolculukta yapılan dua kabul edilir.", s: "Ebû Dâvûd, Tirmizî" },
{ t: "Yolculuğa çıkarken 'Allah'ım, dinimi, ailemi ve malımı sana emanet ediyorum' de.", s: "Riyâzü's-Sâlihîn" },
{ t: "Bir kimse yolculuktan dönünce önce mescide gidip iki rekât namaz kılsın.", s: "Buhârî, Müslim" },
{ t: "Bir adam yolda susuz bir köpeğe su verdi de Allah ona teşekkür etti ve onu bağışladı.", s: "Buhârî, Müslim" },
{ t: "Her canlıya yapılan iyilikte sevap vardır.", s: "Buhârî, Müslim" },
{ t: "Hayvanlara eziyet etmeyin; onlar Allah'ın yarattığı canlılardır.", s: "Riyâzü's-Sâlihîn" },
{ t: "Kim bir serçeyi boş yere öldürürse, kıyamet günü o serçe 'Ya Rab, falan beni faydasız yere öldürdü' diye şikâyet eder.", s: "Nesâî, Sayd 34" },
{ t: "Hayvanların yüzüne vurmayın, dağlamayın; Allah yüzü dağlayana lânet etsin.", s: "Müslim, Libâs 107" },
{ t: "Hayvanlara binerken onlara ağır yük yüklemeyin; hayvanların hakkını gözetin.", s: "Ebû Dâvûd, Cihâd 44" },
{ t: "Kim bir ağaç dikerse, o ağaçtan insan, hayvan ya da kuş yediği sürece ona sadaka yazılır.", s: "Buhârî, Müslim" },
{ t: "Bir Müslüman bir ağaç diker ya da ekin ekerse; ondan kuş, insan veya hayvan yerse, bu onun için sadaka olur.", s: "Buhârî, Müslim" },
{ t: "Kim ölü bir toprağı ihya ederse (ekip biçerse) o toprak onundur.", s: "Buhârî, Hars 15" },
{ t: "Suyu israf etmeyin; akan bir nehirde abdest alsanız bile.", s: "İbn Mâce, Tahâret 48" },
{ t: "Yollara ve gölgeliklere pislik atmayın; lânete sebep olur.", s: "Ebû Dâvûd, Tahâret 14" },
{ t: "Durgun suya bevletmeyin; sonra ondan abdest almayın.", s: "Buhârî, Müslim" },
{ t: "Mescitte tükürmek günahtır; kefareti onu temizlemektir.", s: "Buhârî, Müslim" },
{ t: "Cuma günü gusletmek her ergen için gereklidir.", s: "Buhârî, Müslim" },
{ t: "Cuma günü gusletmek, misvak kullanmak ve güzel koku sürünmek sünnettir.", s: "Buhârî, Müslim" },
{ t: "Kim güzel koku ikram edilirse reddetmesin; o hafiftir ve kokusu hoştur.", s: "Müslim, Elfâz 20" },
{ t: "Sizden biri aksırınca 'Elhamdülillah' desin; kardeşi ona 'Yerhamükellah' desin; o da 'Yehdîkümullâhu ve yuslihu bâleküm' desin.", s: "Buhârî, Edeb 126" },
{ t: "Esneme şeytandandır; biriniz esneyince elini ağzına koysun; şeytan içine girer.", s: "Müslim, Zühd 56" },
{ t: "Sizden biri esnerse elini ağzına koysun; şeytan güler.", s: "Buhârî, Müslim" },
{ t: "Bir kimse güzel bir rüya görürse Allah'a hamd etsin ve anlatsın; kötü rüya görürse Allah'a sığınsın, kimseye anlatmasın.", s: "Buhârî, Müslim" },
{ t: "Karınca, arı, hüdhüd ve göçeğen kuşunu öldürmeyin.", s: "Ebû Dâvûd, Edeb 164" },
{ t: "Bir kediyi hapsedip yedirmeyen kadın cehenneme girdi; bir köpeğe su veren kimse cennete girdi.", s: "Buhârî, Müslim" },
{ t: "Yeryüzü bana mescit ve temiz kılındı; ümmetimden kim namaz vaktine erişirse orada namazını kılsın.", s: "Buhârî, Müslim" },
{ t: "Hastalık bulaşıcı değildir, uğursuzluk yoktur. Ben iyi yorumu (tefeül) severim: Güzel söz.", s: "Buhârî, Müslim" },
{ t: "Uğursuzluk yoktur; hayır Allah'tandır.", s: "Buhârî, Müslim" },
{ t: "Bir yerde vebâ olduğunu duyarsanız oraya girmeyin; bulunduğunuz yerde çıkarsa oradan kaçmayın.", s: "Buhârî, Müslim" },
{ t: "Hastalıklı deveyi sağlam devenin yanına getirmeyin.", s: "Buhârî, Müslim" },
{ t: "Kim güneşten korunmak için sabah kalkarsa … Bedenine afiyet verilmiş, güvende, yiyeceği yanında olan kimse dünyaya sahip gibidir.", s: "Tirmizî, Zühd 34" },
{ t: "Kişi hastalandığında, sağlıklıyken yaptığı amellerin sevabı ona yazılmaya devam eder.", s: "Buhârî, Cihâd 134" },
{ t: "Kul hastalanınca Allah ona iki melek gönderir: 'Bakın, ne diyor?' Kul Allah'a hamd ederse Allah: 'Kulumu iyileştirirsem ona ondan daha hayırlı et ve kan veririm; ruhunu alırsam onu bağışlarım' buyurur.", s: "Muvatta, Ayn 5" },
{ t: "Ateşli hastalık, cehennem sıcağındandır; onu suyla serinletin.", s: "Buhârî, Müslim" },
{ t: "Sağlığınızın kıymetini bilin; sağlık, en büyük nimetlerdendir.", s: "Riyâzü's-Sâlihîn" },
{ t: "Allah'tan afiyet isteyin; imandan sonra afiyetten daha hayırlı bir şey verilmemiştir.", s: "Tirmizî, Deavât 105" },
{ t: "Allah'ım! Bana bedenimde afiyet ver, kulağımda afiyet ver, gözümde afiyet ver.", s: "Ebû Dâvûd, Edeb 101" },
];
